const $=s=>document.querySelector(s);let B=window.pywebview?.api||null, state={page:'dashboard',aid:null,exid:null,theme:'dark',assessmentTab:'overview',aiKind:null,selectedApKey:null,networkSnapshot:null,networkSearch:'',networkBand:'all',networkSort:'signal',wifiAuditAuthorized:false,wifiAuditRunning:false,wifiAuditRecord:null,wifiAuditHistory:[],runningTestId:null,lastTestResult:null},executionSeq=0;
const pages=[['DISCOVERY','dashboard','Wireless Networks'],['ASSESSMENT','assessments','Assessments'],['DISCOVERY','devices','Devices'],['DISCOVERY','map','Network Map'],['AUDIT','wifi_audit','Wi-Fi Security Audit'],['RESEARCH','dataset','Dataset Analysis'],['RESEARCH','capture','Capture Review'],['RESEARCH','defense','Deauthentication Assessment'],['LAB','lab','Lab Simulator'],['SYSTEM','settings','Settings'],['SYSTEM','tools','Tool Integrations']];
function nav(){let n=$('#nav');n.className='nav';n.innerHTML='';let last='';for(const [g,id,label] of pages){if(g!==last){let x=document.createElement('div');x.className='group';x.textContent=g;n.appendChild(x);last=g}let b=document.createElement('button');b.textContent=label;b.dataset.page=id;b.onclick=()=>go(id);n.appendChild(b)}}
function go(p){if(p!==state.page)executionSeq++;clearWifiCredential();state.page=p;render()}
function esc(v){return String(v??'').replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;','\\':'&#92;'}[c]))}
function badge(s){let c=(s||'info').toLowerCase().replace(/[^a-z0-9_-]/g,'');return `<span class="badge sev-${c}">${esc(s||'Unknown')}</span>`}
async function api(method,...args){if(!B){throw Error('PyWebView bridge is not ready. Restart run_simulator.bat.')}return await B[method](...args)}
function toast(m){let t=$('#toast');t.textContent=m;t.style.display='block';setTimeout(()=>t.style.display='none',2500)}
let renderSeq=0;
async function render(){const seq=++renderSeq;document.querySelectorAll('#nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===state.page));$('#title').textContent=pages.find(x=>x[1]===state.page)?.[2]||'WiFiSentinel';let app=$('#app');app.innerHTML='<div class="content page-loading"><div class="loading-card"><span class="spinner"></span><div><b>Loading</b><div class="muted">Opening '+esc(state.page)+' without blocking on live scans.</div></div></div></div>';try{let html=await ({dashboard:dashboard,assessments:assessments,new:newAssessment,wifi:wifi,devices:devices,tests:tests,map:networkMap,attack:attackVectors,execution:execution,findings:findings,evidence:evidence,dataset:dataset,ai:aiAnalysis,posture:posture,reports:reports,settings:settings,tools:tools,capture:captureReview,defense:deauthAssessment,lab:labSimulator,wifi_audit:wifiAudit}[state.page])();if(seq!==renderSeq)return;app.innerHTML=`<div class="content">${html}</div>`;if(state.page==='settings')bindMatrixControls();if(state.page==='new')bindNewAssessment();if(state.page==='assessments'&&state.assessmentTab==='scope')bindScopeForm();}catch(e){if(seq!==renderSeq)return;app.innerHTML=`<div class="content"><div class="notice error-notice"><b>Page error</b><div>${esc(e.message)}</div></div></div>`}}
async function dashboard(){
 const snap=await api('live_snapshot');
 state.networkSnapshot=snap;return `<div id="live-dashboard">${networkDashboard(snap)}</div>`
}
async function wifiAudit(){
 const [snapshot,history]=await Promise.all([api('live_snapshot'),api('wifi_audit_history')]);
 state.wifiAuditHistory=Array.isArray(history)?history:[];
 return window.WiFiSentinelAuditView.render({snapshot,history:state.wifiAuditHistory,
  active:state.wifiAuditRecord,authorized:state.wifiAuditAuthorized,running:state.wifiAuditRunning});
}
async function runWifiAudit(){
 if(!state.wifiAuditAuthorized){toast('Confirm authorization for this connected network first.');return}
 if(state.wifiAuditRunning)return;
 state.wifiAuditRunning=true;render();
 toast('Collecting current OS network evidence…');
 try{
  const result=await api('run_wifi_audit',true);
  if(!result||!result.id){toast(result?.error||'Wi-Fi audit was not saved.');return}
  state.wifiAuditRecord=result;state.wifiAuditHistory=await api('wifi_audit_history');
  toast('Wi-Fi audit saved.');
 }catch(error){toast(error?.message||'Wi-Fi audit failed.');}
 finally{state.wifiAuditRunning=false;render();}
}
function openWifiAudit(auditId){
 const record=state.wifiAuditHistory.find(item=>item.id===auditId);
 if(!record)return;
 state.wifiAuditRecord=record;render();
}
async function markWifiRemediationApplied(auditId,findingId,applied){
 try{
  await api('set_wifi_remediation_applied',auditId,findingId,applied);
  state.wifiAuditHistory=await api('wifi_audit_history');
  state.wifiAuditRecord=state.wifiAuditHistory.find(item=>item.id===auditId)||state.wifiAuditRecord;
  toast(applied?'Marked applied; verification is still required.':'Applied status cleared.');await render();
 }catch(error){toast(error?.message||'Remediation status could not be saved.');}
}
async function exportWifiAuditPdf(auditId){
 const result=await api('export_wifi_audit_pdf',auditId);
 toast(typeof result==='string'?`PDF saved: ${result.split('/').pop()}`:(result?.error||'PDF export failed.'));
}
function clearWifiCredential(){
 const field=$('#wifi-current-credential');if(field){field.value='';field.type='password'}
 for(const id of ['wifi-credential-reveal','wifi-credential-copy','wifi-credential-clear']){const button=$('#'+id);if(button){button.disabled=true;if(id==='wifi-credential-reveal')button.textContent='Reveal'}}
 const status=$('#wifi-credential-status');if(status)status.textContent='Credential cleared from the current view.';
}
async function requestWifiCredential(){
 const status=$('#wifi-credential-status');if(status)status.textContent='Requesting access from the operating system…';
 const requestButton=$('.audit-credential-controls button');if(requestButton)requestButton.disabled=true;
 try{
  let response=await api('get_current_wifi_credential',true);
  if(!response?.ok||typeof response.password!=='string'||!response.password){const reason=response?.reason||'The operating system returned no saved credential.';if(status)status.textContent=reason;toast(reason);return}
  const field=$('#wifi-current-credential');if(!field){response.password='';response=null;return}
  field.value=response.password;field.type='password';response.password='';response=null;
  for(const id of ['wifi-credential-reveal','wifi-credential-clear']){const button=$('#'+id);if(button)button.disabled=false}
  const copy=$('#wifi-credential-copy');if(copy)copy.disabled=true;
  if(status)status.textContent='Credential returned by the operating system and masked. It is transient and will clear when you leave this page or hide the window.';
 }catch(error){const message=error?.message||'The operating system denied credential access.';if(status)status.textContent=message;toast(message)}
 finally{if(requestButton)requestButton.disabled=false}
}
function toggleWifiCredential(){
 const field=$('#wifi-current-credential');if(!field||!field.value)return;
 const revealing=field.type==='password';field.type=revealing?'text':'password';
 const reveal=$('#wifi-credential-reveal');if(reveal)reveal.textContent=revealing?'Hide':'Reveal';
 const copy=$('#wifi-credential-copy');if(copy)copy.disabled=!revealing;
}
async function copyWifiCredential(){
 const field=$('#wifi-current-credential');if(!field||field.type!=='text'||!field.value){toast('Reveal the current credential before copying it.');return}
 try{if(navigator.clipboard?.writeText)await navigator.clipboard.writeText(field.value);else{field.focus();field.select();if(!document.execCommand('copy'))throw Error('Clipboard access is unavailable.')}toast('Current Wi-Fi credential copied.')}
 catch(error){toast(error?.message||'Clipboard access is unavailable; select the revealed value to copy it.')}
}
function apIdentity(a){return window.WiFiSentinelCapabilityState.apIdentity(a)}
function ssidLabel(a){return esc(window.WiFiSentinelCapabilityState.ssidLabel(a))}
function scanSource(w){return window.WiFiSentinelCapabilityState.scanSource(w)}
function networkDashboard(s=state.networkSnapshot||{}){
 state.networkSnapshot=s;const w=s.wifi||{},aps=w.nearby_aps||[],source=scanSource(w);aps.forEach((ap,index)=>{ap._observation_index=index});
 let selected=aps.find(a=>apIdentity(a)===state.selectedApKey)||null;
 if(!selected&&state.selectedApRecord){const match=window.WiFiSentinelCapabilityState.matchObservationIndex(state.selectedApRecord,aps);if(match>=0)selected=aps[match]}
 if(!selected&&!state.selectedApRecord)selected=aps[0]||null;
 if(selected){state.selectedApKey=apIdentity(selected);state.selectedApRecord={...selected}}
 const visible=window.WiFiSentinelCapabilityState.filterAndSortNetworks(aps,{query:state.networkSearch,band:state.networkBand,sort:state.networkSort});
 const selectedKey=selected?apIdentity(selected):null;
 const detail=selected?renderNetworkDetail(selected,w,source):'<div class="empty">Select a real scan observation to inspect available details and tools.</div>';
 const liveState=window.WiFiSentinelCapabilityState.scanStatus(s);
 const countLabel=window.WiFiSentinelCapabilityState.networkCountLabel(s);
 return `<div class="live-hero"><div><div class="eyebrow">WIRELESS OBSERVATIONS · ${esc(source)}</div><h2>${esc(countLabel)}</h2><div class="live-meta"><span class="live-dot ${liveState.toLowerCase().replaceAll(' ','-')}"></span><b id="network-live-state">${liveState}</b><span>${esc(w.interface||'Built-in or attached Wi-Fi interface')}</span><span id="network-last-scan">Last successful scan ${esc(w.observed_at||s.observed_at||'pending')}</span></div><div id="network-scan-error" class="muted" style="margin-top:8px;${window.WiFiSentinelCapabilityState.scanMessage(s,w)?'':'display:none'}">${esc(window.WiFiSentinelCapabilityState.scanMessage(s,w))}</div></div><button class="primary" onclick="refreshLiveNow(true)">Scan nearby networks</button></div>
 <div class="grid g2" style="margin-top:14px"><div class="panel"><div class="panel-head"><div><b>Nearby networks</b><div class="muted">Actual OS scan results; no automatic connection</div></div><span class="live-chip">${liveState}</span></div><div class="panel-body"><div class="network-controls"><input aria-label="Search networks" placeholder="Search SSID, BSSID, band, channel, signal, security…" value="${esc(state.networkSearch)}" oninput="state.networkSearch=this.value;updateNetworkList()"><select aria-label="Filter band" onchange="state.networkBand=this.value;updateNetworkList()"><option value="all" ${state.networkBand==='all'?'selected':''}>All reported bands</option><option value="2.4" ${state.networkBand==='2.4'?'selected':''}>2.4 GHz</option><option value="5" ${state.networkBand==='5'?'selected':''}>5 GHz</option><option value="6" ${state.networkBand==='6'?'selected':''}>6 GHz</option></select><select aria-label="Sort networks" onchange="state.networkSort=this.value;updateNetworkList()"><option value="signal" ${state.networkSort==='signal'?'selected':''}>Signal</option><option value="name" ${state.networkSort==='name'?'selected':''}>Name</option><option value="bssid" ${state.networkSort==='bssid'?'selected':''}>BSSID</option><option value="band" ${state.networkSort==='band'?'selected':''}>Band</option><option value="channel" ${state.networkSort==='channel'?'selected':''}>Channel</option><option value="security" ${state.networkSort==='security'?'selected':''}>Security</option></select></div><div id="network-list" class="table-wrap">${renderNetworkRows(visible,selectedKey)}</div></div></div><div id="network-details">${detail}</div></div>
 <div class="live-foot"><span>Source: ${esc(source)} · AP client association counts and PMF are not exposed by this scan.</span><span>${w.freshness==='cached'?'Showing cached observations at their original observation times.':''}</span></div>`
}
function renderNetworkDetail(selected,w,source){
 const fields=[['SSID',selected.ssid||((selected.ssid_observed&&selected.ssid_hidden)?'Hidden SSID':null)],
  ['SSID observation',selected.ssid_observed===true?(selected.ssid_hidden?'Hidden SSID explicitly observed':'SSID value observed'):null],
  ['SSID bytes (hex)',selected.ssid_data_hex],['BSSID',selected.bssid],['Security advertised',selected.auth],['Cipher suites',selected.cipher],
  ['Channel',selected.channel],['Band',selected.band==null?null:`${selected.band} GHz`],['Frequency',selected.frequency_ghz==null?null:`${selected.frequency_ghz} GHz`],
  ['Signal',selected.signal_dbm!=null?`${selected.signal_dbm} dBm`:selected.signal_pct!=null?`${selected.signal_pct}%`:null],
  ['Radio type',selected.radio_type],['Interface',selected.interface||w.interface],['Source',selected.source||source],
  ['Scan method',selected.scan_method||w.scan_method],['Network type',selected.network_type],['Vendor',selected.vendor],
  ['Associated clients',selected.client_count],['First observed',selected.first_seen],['Last observed',selected.last_seen||selected.observed_at||w.observed_at]];
 const optional=[['Channel width',selected.channel_width],['Beacon interval',selected.beacon_interval_ms==null?null:`${selected.beacon_interval_ms} ms`],
  ['Country code',selected.country_code],['Noise',selected.noise_dbm==null?null:`${selected.noise_dbm} dBm`],['IBSS network',selected.ibss],
  ['Supported rates',selected.supported_rates_mbps?.length?selected.supported_rates_mbps.map(x=>`${x} Mbps`).join(', '):null],
  ['Capability flags',selected.capability_flags?.length?selected.capability_flags.join(', '):null],
  ['PMF advertisement',selected.pmf_advertisement?`Capable: ${selected.pmf_advertisement.advertised_capable}; required: ${selected.pmf_advertisement.advertised_required}; enforcement: unknown`:null],
  ['Information elements',selected.information_elements?.length?selected.information_elements.map(x=>`${x.name} (ID ${x.id}, ${x.length} bytes)`).join('; '):null]];
 const allFields=[...fields,...optional],available=allFields.filter(([,v])=>v!==null&&v!==undefined&&v!==''),missing=allFields.filter(([,v])=>v===null||v===undefined||v==='').map(([label])=>label);
 const detailRows=rows=>rows.map(([label,val])=>`<div><span>${esc(label)}</span><b>${esc(val)}</b></div>`).join('');
 const rawValue=value=>value&&typeof value==='object'?JSON.stringify(value):value;
 const diagnostics=selected.diagnostic_fields?`<div class="table-wrap"><table class="table"><thead><tr><th>Field</th><th>Native value</th><th>Normalized value</th></tr></thead><tbody>${Object.entries(selected.diagnostic_fields).map(([field,pair])=>`<tr><td>${esc(field)}</td><td>${esc(rawValue(pair.native)??'Not returned')}</td><td>${esc(rawValue(pair.normalized)??'Not normalized')}</td></tr>`).join('')}</tbody></table></div>`:'';
 const rawDetails=diagnostics||selected.information_elements?.length?`<details class="radio-details"><summary>Raw Source Data</summary><div class="muted">Sanitized scalar source fields and information-element ID/name/length only. Frame payload bytes are not exposed.</div>${diagnostics}${selected.information_elements?.length?`<div class="table-wrap"><table class="table"><thead><tr><th>IE ID</th><th>Element</th><th>Length</th></tr></thead><tbody>${selected.information_elements.map(x=>`<tr><td>${esc(x.id)}</td><td>${esc(x.name)}</td><td>${esc(x.length)} bytes</td></tr>`).join('')}</tbody></table></div>`:''}</details>`:'';
 const missingDetails=missing.length?`<details class="radio-details"><summary>Fields not exposed by this source (${missing.length})</summary><div class="muted">These values were absent from the selected scan record; WiFiSentinel does not infer them.</div><div class="muted">${missing.map(esc).join(' · ')}</div>${selected.vendor_note?`<div class="muted">${esc(selected.vendor_note)}</div>`:''}${selected.client_count_note?`<div class="muted">${esc(selected.client_count_note)}</div>`:''}${w.identifier_limitation?`<div class="muted">${esc(w.identifier_limitation)}</div>`:''}</details>`:'';
 return `<div class="network-detail"><div class="panel-head"><div><b>${ssidLabel(selected)}</b><div class="muted">BSSID ${esc(selected.bssid||'Not reported by source')}</div></div><span class="live-chip">${w.freshness==='cached'?'CACHED OBSERVATION':'OBSERVED'}</span></div><div class="panel-body"><div class="detail-grid">${detailRows(available.filter(([label])=>fields.some(([name])=>name===label)))}</div><details class="radio-details"><summary>Full Radio Details</summary>${optional.some(([label])=>available.some(([availableLabel])=>label===availableLabel))?`<div class="detail-grid">${detailRows(available.filter(([label])=>optional.some(([name])=>name===label)))}</div>`:'<div class="muted">This scan source returned no additional radio metadata.</div>'}${selected.ssid_data_hex?`<div class="muted">Exact SSID bytes: ${esc(selected.ssid_data_hex)}</div>`:''}</details>${rawDetails}${missingDetails}<div class="row-actions" style="margin-top:14px"><button class="primary" onclick="analyzeSelectedNetwork()">Analyze advertised security</button><button class="ghost" onclick="prepareNetworkCaptureReview()">Review offline capture</button><button class="ghost" onclick="go('dataset')">Review separate research dataset</button><button class="ghost" onclick="addSelectedNetworkToLab()">Use SSID in lab simulator</button></div><div class="muted" style="margin-top:10px">This observation does not establish reachability, AP ownership, PMF status, vulnerabilities, or associated clients. PMF enforcement remains unknown unless source evidence reports its advertisement.</div>${state.networkReview?renderNetworkReview(state.networkReview):''}</div></div>`
}
function renderNetworkRows(visible,selectedKey){const aps=(state.networkSnapshot?.wifi?.nearby_aps)||[],snap=state.networkSnapshot||{},attempt=snap.scan_attempt||{};return visible.length?`<table class="table live-table"><thead><tr><th>Network</th><th>BSSID</th><th>Band / channel</th><th>Signal</th><th>Security</th></tr></thead><tbody>${visible.map(({a,index})=>`<tr tabindex="0" role="button" class="network-row ${apIdentity(a)===selectedKey?'selected-row':''}" onclick="selectNetwork(${index})" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();selectNetwork(${index})}"><td><b>${ssidLabel(a)}</b></td><td class="mono">${esc(a.bssid)||'Not reported by source'}</td><td>${a.band!=null?`${esc(a.band)} GHz`:a.frequency_ghz!=null?`${esc(a.frequency_ghz)} GHz`:'Band unavailable'}${a.channel!=null?` · ch ${esc(a.channel)}`:''}</td><td>${a.signal_dbm!=null?`${esc(a.signal_dbm)} dBm`:a.signal_pct!=null?`${esc(a.signal_pct)}%`:'Not reported'}</td><td>${esc(a.auth)||'Not reported'}</td></tr>`).join('')}</tbody></table>`:aps.length?'<div class="empty">No observations match these filters.</div>':(snap.refreshing||attempt.status==='scanning')?'<div class="empty">Scanning for nearby networks. No scan result is available yet.</div>':attempt.status==='empty'?'<div class="empty"><b>The latest successful scan returned no access points.</b><br><span class="muted">Earlier observations remain available in history.</span></div>':`<div class="empty"><b>No current scan result is available.</b><br><span class="muted">${esc(window.WiFiSentinelCapabilityState.scanMessage(snap)||'Check that Wi-Fi is enabled and grant the OS permissions requested for scanning.')}</span></div>`}
function selectNetwork(index){const aps=state.networkSnapshot?.wifi?.nearby_aps||[];if(!aps[index])return;state.selectedApKey=apIdentity(aps[index]);state.selectedApRecord={...aps[index]};state.networkReview=null;state.networkAI=null;state.aid=null;const host=$('#network-details'),list=$('#network-list'),w=state.networkSnapshot?.wifi||{};if(host)host.innerHTML=renderNetworkDetail(aps[index],w,scanSource(w));if(list)list.innerHTML=renderNetworkRows(filteredNetworks(),state.selectedApKey)}
function filteredNetworks(){const aps=state.networkSnapshot?.wifi?.nearby_aps||[];return window.WiFiSentinelCapabilityState.filterAndSortNetworks(aps,{query:state.networkSearch,band:state.networkBand,sort:state.networkSort})}
function updateNetworkList(){const list=$('#network-list');if(list)list.innerHTML=renderNetworkRows(filteredNetworks(),state.selectedApKey)}
function addSelectedNetworkToLab(){const ap=(state.networkSnapshot?.wifi?.nearby_aps||[]).find(x=>apIdentity(x)===state.selectedApKey);state.pendingLabSsid=ap?.ssid||'';go('lab')}
function renderNetworkReview(r){return `<div class="panel" style="margin-top:14px"><div class="panel-head"><b>Saved advertised-security review</b><span>${badge('OBSERVATION')}</span></div><div class="panel-body"><p>${esc(r.summary)}</p><div class="muted">No active connection or packet inspection was performed. PMF: unknown (not reported by the OS scan).</div><div class="row-actions" style="margin-top:12px"><button class="ghost" onclick="downloadNetworkReport('json')">Export JSON</button><button class="ghost" onclick="downloadNetworkReport('csv')">Export CSV</button><button class="primary" onclick="downloadNetworkReport('pdf')">Export PDF</button><button class="ghost" onclick="runSelectedNetworkAI()">AI review</button></div>${state.networkAI?`<div class="ai-section">${aiRender(state.networkAI)}</div>`:''}</div></div>`}
async function analyzeSelectedNetwork(){const ap=(state.networkSnapshot?.wifi?.nearby_aps||[]).find(x=>apIdentity(x)===state.selectedApKey);if(!ap)return;try{let r=await api('network_observation_history',ap);if(!r)r=await api('analyze_network_observation',ap);state.aid=r.assessment_id;state.networkReview=r.review;const host=$('#network-details'),w=state.networkSnapshot?.wifi||{};if(host)host.innerHTML=renderNetworkDetail(ap,w,scanSource(w));toast(r.evidence_id?'Saved observation opened':'Observation saved')}catch(e){toast(e.message||String(e))}}
async function prepareNetworkCaptureReview(){await analyzeSelectedNetwork();if(state.aid)go('capture')}
async function downloadNetworkReport(kind){if(!state.aid)return;const r=await api(kind==='json'?'export_json':kind==='csv'?'export_csv':'export_pdf',state.aid);if(typeof r==='object'&&r?.error)toast(r.error);else toast(`Report saved: ${String(r).split('/').pop()}`)}
