function wifiFacts(w){return `<div class="grid g2"><div class="card"><div class="label">SSID</div><b>${esc(w.ssid)||'—'}</b></div><div class="card"><div class="label">BSSID</div><b class="mono">${esc(w.bssid)||'—'}</b></div><div class="card"><div class="label">Authentication</div><b>${esc(w.auth)||'—'}</b></div><div class="card"><div class="label">Cipher</div><b>${esc(w.cipher)||'—'}</b></div><div class="card"><div class="label">Signal</div><b>${w.signal_pct!=null?w.signal_pct+'%':w.signal_dbm!=null?w.signal_dbm+' dBm':'—'} ${w.signal_dbm==null?'':`(${w.signal_dbm} dBm)`}</b></div><div class="card"><div class="label">Channel</div><b>${w.channel??'—'}</b></div></div>`}
async function assessments(){
 let rows=await api('assessments');
 let counts={total:rows.length,ready:rows.filter(x=>x.status==='ready').length,running:rows.filter(x=>x.status==='running').length,completed:rows.filter(x=>x.status==='completed').length,failed:rows.filter(x=>x.status==='failed').length};
 let selected=state.aid?rows.find(x=>x.id===state.aid):null;
 if(!selected && rows.length){state.aid=rows[0].id;selected=rows[0]}
 let tabs=[['overview','Overview'],['scope','Scope'],['tests','Security Tests'],['execution','Execution'],['attack','Attack Vectors'],['findings','Findings'],['evidence','Evidence'],['ai','AI Analysis'],['posture','Security Posture'],['reports','Reports']];
 let workspace='';
 if(selected){
   let st=await api('assessment',selected.id);let fs=st.findings||[],ev=st.evidence||[];
   if(state.assessmentTab==='overview') workspace=`<div class="grid g4"><div class="card"><div class="label">Status</div><div class="metric" style="font-size:18px">${badge(selected.status)}</div></div><div class="card"><div class="label">Findings</div><div class="metric">${fs.length}</div></div><div class="card"><div class="label">Evidence</div><div class="metric">${ev.length}</div></div><div class="card"><div class="label">Authorization</div><div class="metric" style="font-size:18px">${selected.authorization?'<span class="ok">Confirmed</span>':'<span class="bad">Required</span>'}</div></div></div><div class="grid g2" style="margin-top:14px"><div class="panel"><div class="panel-head"><b>Assessment summary</b></div><div class="panel-body"><div class="kpi"><span>Name</span><b>${esc(selected.name)}</b></div><div class="kpi"><span>Target</span><b>${esc(selected.target)||'—'}</b></div><div class="kpi"><span>Tester</span><b>${esc(selected.tester)||'—'}</b></div><div class="kpi"><span>Environment</span><b>${esc(selected.environment)||'—'}</b></div><div class="kpi"><span>Created</span><b>${esc(selected.created_at)}</b></div></div></div><div class="panel"><div class="panel-head"><b>Assessment workflow</b></div><div class="panel-body"><div class="workflow-grid"><button class="workflow" onclick="assessmentTab('scope')"><b>1. Scope</b><span>Review authorization and declared targets.</span></button><button class="workflow" onclick="assessmentTab('tests')"><b>2. Test</b><span>Run only supported, scoped security tests.</span></button><button class="workflow" onclick="assessmentTab('execution')"><b>3. Execute</b><span>Collect and persist actual observations.</span></button><button class="workflow" onclick="assessmentTab('findings')"><b>4. Findings</b><span>Review evidence-backed results.</span></button><button class="workflow" onclick="assessmentTab('ai')"><b>5. AI analysis</b><span>Interpret persisted evidence with OpenAI.</span></button><button class="workflow" onclick="assessmentTab('reports')"><b>6. Report</b><span>Export JSON, CSV and PDF results.</span></button></div></div></div></div>`;
   else if(state.assessmentTab==='scope') workspace=`<form id="scope-form" class="grid g2"><div class="panel"><div class="panel-head"><b>Assessment scope and authorization</b></div><div class="panel-body form"><div class="field"><label for="scope-name">Assessment name</label><input id="scope-name" name="name" required value="${esc(selected.name)}"></div><div class="field"><label for="scope-target">Target</label><input id="scope-target" name="target" value="${esc(selected.target)}"></div><div class="field"><label for="scope-wireless">Wireless scope</label><input id="scope-wireless" name="wireless_scope" value="${esc(selected.wireless_scope)}" placeholder="Exact SSID(s) or BSSID(s), comma separated"></div><div class="field"><label for="scope-network">Network scope</label><input id="scope-network" name="network_scope" value="${esc(selected.network_scope)}" placeholder="IP address or CIDR, comma separated"></div><div class="field"><label for="scope-interface">Interface</label><input id="scope-interface" name="interface" value="${esc(selected.interface)}"></div><div class="field"><label for="scope-notes">Scope notes</label><textarea id="scope-notes" name="notes">${esc(selected.notes)}</textarea></div><label class="check"><input name="authorized" type="checkbox" ${selected.authorization?'checked':''}> I confirm current explicit authorization for these targets.</label><div class="field"><label for="scope-authorized-by">Authorized by</label><input id="scope-authorized-by" name="authorized_by" value="${esc(selected.authorized_by)}"></div><div class="field"><label for="scope-auth-note">Authorization reference / notes</label><textarea id="scope-auth-note" name="authorization_note">${esc(selected.authorization_note)}</textarea></div><button class="primary" type="submit">Save scope and authorization</button></div></div><div class="panel"><div class="panel-head"><b>Execution boundary</b></div><div class="panel-body"><div class="notice">Network tests require an IP/CIDR scope. Wireless assessment results are persisted only for declared SSIDs or BSSIDs. Connector-backed operations require the authorized connector.</div><p class="muted" style="margin-top:12px">Saving without the authorization checkbox revokes authorization and blocks further execution.</p></div></div></form>`;
   else if(state.assessmentTab==='tests') workspace=await tests();
   else if(state.assessmentTab==='execution') workspace=await execution();
   else if(state.assessmentTab==='attack') workspace=await attackVectors();
   else if(state.assessmentTab==='findings') workspace=await findings();
   else if(state.assessmentTab==='evidence') workspace=await evidence();
   else if(state.assessmentTab==='ai') workspace=await aiAnalysis();
   else if(state.assessmentTab==='posture') workspace=await posture();
   else if(state.assessmentTab==='reports') workspace=await reports();
 }
 return `<div class="assessment-head"><div><div class="eyebrow">ASSESSMENT WORKSPACE</div><h2 style="margin:4px 0 4px">${selected?esc(selected.name):'Assessments'}</h2><div class="muted">${selected?esc(selected.target||'No target declared'):'Create, open and manage authorized wireless security assessments from one workspace.'}</div></div><div class="row-actions"><button class="ghost" onclick="render()">Refresh</button><button class="primary" onclick="go('new')">New assessment</button></div></div>
 <div class="grid g5 stat-row"><div class="card"><div class="label">Total</div><div class="metric">${counts.total}</div></div><div class="card"><div class="label">Ready</div><div class="metric">${counts.ready}</div></div><div class="card"><div class="label">Running</div><div class="metric">${counts.running}</div></div><div class="card"><div class="label">Completed</div><div class="metric">${counts.completed}</div></div><div class="card"><div class="label">Failed</div><div class="metric">${counts.failed}</div></div></div>
 <div class="panel" style="margin-top:14px"><div class="panel-head"><b>Assessment registry</b><span class="muted">${rows.length} persisted assessment${rows.length===1?'':'s'}</span></div><div class="panel-body table-wrap"><table class="table"><thead><tr><th>Name / ID</th><th>Status</th><th>Authorization</th><th>Target</th><th>Wireless scope</th><th>Network scope</th><th>Findings</th><th>Last execution</th><th>Updated</th><th></th></tr></thead><tbody>${rows.map(a=>`<tr class="${state.aid===a.id?'selected-row':''}"><td><b>${esc(a.name)}</b><div class="muted mono">${esc(a.id)}</div></td><td>${badge(a.status)}</td><td>${a.authorization?'<span class="ok">Authorized</span>':'<span class="bad">Not authorized</span>'}</td><td>${esc(a.target)||'—'}</td><td>${esc(a.wireless_scope)||'—'}</td><td class="mono">${esc(a.network_scope)||'—'}</td><td>${a.findings_count||0}<div class="muted">Critical ${a.critical_count||0} · High ${a.high_count||0} · Medium ${a.medium_count||0}</div></td><td>${esc(a.last_execution_at)||'—'}</td><td>${esc(a.updated_at)||'—'}</td><td><button class="ghost" onclick="openAssessment('${a.id}')">Open</button></td></tr>`).join('')}</tbody></table>${rows.length?'':'<div class="empty"><b>No assessments have been created.</b><br><span class="muted">Nothing is fabricated or seeded. Create your first authorized assessment to unlock the assessment workspace.</span><br><button class="primary" style="margin-top:12px" onclick="go(\'new\')">Create first assessment</button></div>'}</div></div>
 ${selected?`<div class="panel" style="margin-top:14px"><div class="panel-head"><div><b>Assessment workspace</b><span class="muted" style="margin-left:8px">${esc(selected.id)}</span></div><span>${badge(selected.status)}</span></div><div class="panel-body"><div class="tabs">${tabs.map(([id,label])=>`<button class="tab ${state.assessmentTab===id?'active':''}" onclick="assessmentTab('${id}')">${label}</button>`).join('')}</div>${workspace}</div></div>`:`<div class="grid g3 feature-grid" style="margin-top:14px"><div class="card"><b>Scope & authorization</b><p class="muted">Declare the wireless and network boundaries before any execution.</p></div><div class="card"><b>Security testing</b><p class="muted">Use the local Windows capabilities or an authorized Kali connector.</p></div><div class="card"><b>Evidence & findings</b><p class="muted">Persist actual observations, findings and execution events for review.</p></div><div class="card"><b>AI analysis</b><p class="muted">Use OpenAI to interpret persisted evidence without inventing telemetry.</p></div><div class="card"><b>Security posture</b><p class="muted">Review a deterministic posture summary and evidence gaps.</p></div><div class="card"><b>Reporting</b><p class="muted">Export assessment state, findings and executive analysis.</p></div></div>`}`;
}
async function openAssessment(id){executionSeq++;state.aid=id;state.exid=null;state.assessmentTab='overview';state.page='assessments';await render()}
function assessmentTab(tab){if(tab!=='execution')executionSeq++;state.assessmentTab=tab;render()}

function newAssessment(){return `<div class="grid g2"><div class="panel"><div class="panel-head"><b>Assessment definition</b></div><div class="panel-body"><form id="af" class="form"><div class="field"><label>Name</label><input name="name" required value="Wireless Security Assessment"></div><div class="field"><label>Target</label><input name="target" placeholder="SSID, site, or host scope" required></div><div class="field"><label>Description</label><textarea name="description">Authorized wireless security assessment.</textarea></div><div class="field"><label>Tester</label><input name="tester" value="Security Team"></div><div class="field"><label>Environment</label><input name="environment" value="Controlled / authorized environment"></div><div class="field"><label>Wireless scope</label><input name="wireless_scope" placeholder="SSID(s), BSSID(s), or adapter scope"></div><div class="field"><label>Network scope</label><input name="network_scope" placeholder="e.g. 192.168.1.0/24 or 192.168.1.1" required></div><div class="field"><label>Interface</label><input name="interface" placeholder="Optional Wi-Fi adapter name"></div><label class="check"><input type="checkbox" name="authorization"> I confirm that I have explicit authorization to assess the declared target and network scope.</label><button class="primary" type="submit">Create assessment</button></form></div></div><div class="panel"><div class="panel-head"><b>Execution boundary</b></div><div class="panel-body"><div class="step"><b>1. Define scope</b><br><span class="muted">Targets outside the declared network scope are rejected by network tests.</span></div><div class="step"><b>2. Authorize</b><br><span class="muted">Execution cannot start without an explicit authorization flag.</span></div><div class="step"><b>3. Preflight</b><br><span class="muted">The engine checks Windows Wi-Fi, ARP, dataset and connector capabilities.</span></div><div class="step"><b>4. Execute</b><br><span class="muted">Only observations actually collected are persisted as evidence.</span></div></div></div></div>`}
function bindNewAssessment(){const form=$('#af');if(!form)return;form.onsubmit=async e=>{e.preventDefault();const submit=form.querySelector('button[type=submit]');if(submit)submit.disabled=true;const o=Object.fromEntries(new FormData(form));o.authorization=form.authorization.checked;try{const a=await api('create_assessment',o);if(!a||!a.id)throw Error('Assessment creation returned no assessment ID.');state.aid=a.id;state.exid=null;toast('Assessment created');state.page='execution';await render();}catch(x){toast(x.message||String(x));if(submit)submit.disabled=false;}}}
function bindScopeForm(){const form=$('#scope-form');if(!form)return;form.onsubmit=async e=>{e.preventDefault();const submit=form.querySelector('button[type=submit]');if(submit)submit.disabled=true;const values=Object.fromEntries(new FormData(form));try{await api('update_assessment',state.aid,{name:values.name,target:values.target,wireless_scope:values.wireless_scope,network_scope:values.network_scope,interface:values.interface,notes:values.notes});await api('record_authorization',state.aid,form.authorized.checked,values.authorization_note,values.authorized_by);toast('Scope and authorization saved');await render()}catch(error){toast(error.message||String(error));if(submit)submit.disabled=false}}}
async function wifi(){const s=await api('live_snapshot');state.networkSnapshot=s;return `<div id="live-dashboard">${networkDashboard(s)}</div>`}
async function networkMap(){const s=await api('live_snapshot'),ds=s.devices||[],aps=(s.wifi||{}).nearby_aps||[];return `<div class="notice">These are two independent OS observations. The OS WLAN scan and local neighbor cache do not expose device-to-access-point association relationships.</div><div class="grid g2" style="margin-top:14px"><div class="panel"><div class="panel-head"><div><b>Observed wireless networks</b><div class="muted">Source: ${esc((s.wifi||{}).capability==='macos_native'?'macOS Wi-Fi':(s.wifi||{}).capability==='windows_netsh'?'Windows WLAN':'Host Wi-Fi')} scan</div></div><span class="muted">${aps.length} observed</span></div><div class="panel-body table-wrap"><table class="table"><thead><tr><th>SSID</th><th>BSSID</th><th>Band</th><th>Channel</th><th>Radio</th><th>Signal</th></tr></thead><tbody>${aps.map(a=>`<tr><td>${ssidLabel(a)}</td><td class="mono">${esc(a.bssid)||'Not exposed'}</td><td>${a.frequency_ghz?esc(a.frequency_ghz+' GHz'):'Not available'}</td><td>${a.channel??'Not available'}</td><td>${esc(a.radio_type)||'Not available'}</td><td>${a.signal_pct!=null?a.signal_pct+'%':a.signal_dbm!=null?a.signal_dbm+' dBm':'Not available'}</td></tr>`).join('')}</tbody></table>${aps.length?'':'<div class="empty">No wireless networks currently exposed.</div>'}</div></div><div class="panel"><div class="panel-head"><div><b>Local observed devices</b><div class="muted">Source: operating-system neighbor cache</div></div><span class="muted">${ds.length} entries</span></div><div class="panel-body table-wrap"><table class="table"><thead><tr><th>IP</th><th>MAC</th><th>Hostname</th><th>Neighbor state</th><th>Role</th></tr></thead><tbody>${ds.map(d=>`<tr><td class="mono">${esc(d.ip)}</td><td class="mono">${esc(d.mac)}</td><td>${esc(d.hostname)||'Unknown'}</td><td>${esc(d.status)||'Unknown'}</td><td>${d.is_gateway?'Gateway':d.is_self?'This host':'Local neighbor'}</td></tr>`).join('')}</tbody></table>${ds.length?'':'<div class="empty">No local neighbor entries currently exposed.</div>'}</div></div></div>`}
async function attackVectors(){if(!state.aid)return `<div class="notice">Open an assessment to view its supported test catalog.</div>`;const groups=(await api('test_catalog',state.aid)).groups||[];const items=groups.flatMap(g=>g.tests).filter(t=>t.active||/validation|handshake|management-frame/i.test(t.name));return `<div class="hero"><h2>Attack vector validation</h2><div class="muted">Only explicitly authorized, supported tests are available. Active wireless operations require the configured connector and declared wireless scope.</div></div><div class="grid g2">${items.map(t=>`<div class="card"><div class="split"><b>${esc(t.name)}</b>${badge(t.execution_path)}</div><p class="muted">${esc(t.purpose)}</p><div class="muted">${esc(t.status_reason||'Available')}</div><button class="ghost" onclick="runOne('${esc(t.id)}')" ${t.blocked?'disabled':''}>Validate</button></div>`).join('')||'<div class="empty">No attack validation tests are exposed by the catalog.</div>'}</div>`}
async function posture(){if(!state.aid)return '<div class="notice">Open an assessment first.</div>';let st=await api('assessment',state.aid),fs=st.findings;let score=Math.max(0,100-(fs.filter(x=>x.severity==='Critical').length*25+fs.filter(x=>x.severity==='High').length*15+fs.filter(x=>x.severity==='Medium').length*7+fs.filter(x=>x.severity==='Low').length*2));return `<div class="grid g3"><div class="card"><div class="label">Posture score</div><div class="metric">${score}</div><div class="bar" style="margin-top:10px"><i style="width:${score}%"></i></div></div><div class="card"><div class="label">Findings</div><div class="metric">${fs.length}</div></div><div class="card"><div class="label">Assessment</div><div class="metric" style="font-size:16px">${esc(st.assessment.status)}</div></div></div><div class="panel" style="margin-top:14px"><div class="panel-head"><b>Posture basis</b></div><div class="panel-body"><p class="muted">The score is a deterministic summary of persisted findings: Critical 25 points, High 15, Medium 7 and Low 2 per finding, bounded to 0–100. It is a reporting aid, not a compliance certification.</p></div></div>`}
async function devices(){
 const s=await api('live_snapshot');if(!deviceScanJob){deviceScanJob=await api('latest_device_discovery');activeDeviceResults=deviceScanJob?.results||[]}const n=s.network||{},cached=s.devices||[],active=activeDeviceResults||[],history=await api('observation_history','device'),captureImports=await api('capture_history');
 if(captureStationCaptureId&&!captureStationRowsLoaded){try{const item=await api('capture_analysis',captureStationCaptureId);captureStationRows=item.analysis?.station_observations||[]}catch{captureStationRows=[]}captureStationRowsLoaded=true}
 const status=s.refreshing?'REFRESHING':s.collection_error?'CACHED / ERROR':s.ready?'OS CACHE READ':'COLLECTING',scan=deviceScanJob;
 deviceRecords=[...cached.map(d=>({source:'OS neighbor cache',record:d})),...active.map(d=>({source:'Authorized ICMP echo',record:d}))];
 const rowsFor=(ds,source)=>ds.map((d,index)=>`<tr class="selectable-row" onclick="inspectDeviceObservation('${source}',${index})"><td class="mono">${esc(d.ip)}</td><td class="mono">${esc(d.mac)||'Not exposed'}</td><td>${esc(d.hostname)||'Unresolved'}</td><td>${esc(d.type)||'Unknown'}</td><td>${esc(d.vendor)||'Unavailable'}</td><td>${esc(d.interface)||'Not exposed'}</td><td>${badge(d.status)}</td><td class="mono">${esc(d.observed_at)||'Not available'}</td></tr>`).join('');
 const histRows=history.map(h=>`<tr><td>${esc(h.source)}</td><td>${esc(h.method)}</td><td>${esc(h.interface)||'Not reported'}</td><td>${h.results.length} records</td><td>${esc(h.first_seen)}</td><td>${esc(h.last_seen)}</td><td>${badge(h.data_class)}</td></tr>`).join('');
 return `<div id="devices-live"><div class="live-hero"><div><div class="eyebrow">LOCAL DEVICE OBSERVATIONS</div><h2>${esc(n.network||'Local network unavailable')}</h2><div class="live-meta"><span class="live-dot ${status.toLowerCase()}"></span><b>${status}</b><span>${cached.length+active.length} separate observations</span><span>Collected ${esc(s.observed_at||'Not available')}</span></div></div><button class="ghost" onclick="refreshLiveNow()">Refresh OS cache</button></div>
 <div class="grid g4 live-kpis">
  <div class="card kpi-live">
    <div class="label">Observed entries</div>
    <div class="metric">${cached.length + active.length}</div>
  </div>
  <div class="card kpi-live">
    <div class="label">Gateway</div>
    <div class="metric" style="font-size:17px">${esc(n.gateway)||'—'}</div>
  </div>
  <div class="card kpi-live">
    <div class="label">Local IP</div>
    <div class="metric" style="font-size:17px">${esc(n.local_ip)||'—'}</div>
  </div>
  <div class="card kpi-live">
    <div class="label">Interface</div>
    <div class="metric" style="font-size:17px">${esc(n.interface)||'—'}</div>
  </div>
</div>
 <div class="panel" style="margin-top:14px"><div class="panel-head"><div><b>Authorized local discovery</b><div class="muted">One bounded ICMP probe per address on the current private IPv4 subnet only (maximum 256 addresses).</div></div></div><div class="panel-body"><div class="notice">Only responders are listed. Host firewalls may block probes; a host that does not answer is not considered absent. No ports are scanned.</div><label class="check" style="margin:12px 0"><input id="device-scan-authorized" type="checkbox" onchange="$('#device-scan-start').disabled=!this.checked"> I am authorized to send ICMP probes on <b>${esc(n.network||'the detected local subnet')}</b>.</label><div id="device-scan-actions" class="row-actions"><button id="device-scan-start" class="primary" disabled onclick="startDeviceDiscovery()">Start one bounded scan</button>${scan?.status==='running'?'<button class="ghost" onclick="cancelDeviceDiscovery()">Cancel</button>':''}</div><div id="device-scan-status" class="muted" style="margin-top:10px">${scan?renderDeviceScanStatus(scan):'No active discovery scan.'}</div></div></div>
 <div class="panel" style="margin-top:14px"><div class="panel-head"><div><b>OS neighbor-cache observations</b><div class="muted">A cache entry is not proof of current availability. Select a row for source-specific detail.</div></div><span class="muted">${cached.length} records</span></div><div class="panel-body table-wrap"><table class="table live-table"><thead><tr><th>IP</th><th>MAC</th><th>Hostname</th><th>Type</th><th>Vendor</th><th>Interface</th><th>State</th><th>Observed at</th></tr></thead><tbody>${rowsFor(cached,'neighbor')}</tbody></table>${cached.length?'':'<div class="empty">No neighbor-cache observations are currently available.</div>'}</div></div>
 <div class="panel" style="margin-top:14px"><div class="panel-head"><div><b>Authorized ICMP responders</b><div class="muted">These are separate active observations; they are not merged with neighbor-cache entries.</div></div><span class="muted">${active.length} responders</span></div><div class="panel-body table-wrap"><table class="table live-table"><thead><tr><th>IP</th><th>MAC</th><th>Hostname</th><th>Type</th><th>Vendor</th><th>Interface</th><th>State</th><th>Observed at</th></tr></thead><tbody>${rowsFor(active,'icmp')}</tbody></table>${active.length?'':'<div class="empty">No saved ICMP responders. A bounded probe requires explicit authorization above.</div>'}</div></div>
 <div class="panel" style="margin-top:14px"><div class="panel-head"><div><b>Imported-capture station observations</b><div class="muted">Capture-scoped passive 802.11 frame evidence. It does not represent live devices.</div></div></div><div class="panel-body"><label>Imported capture<select id="device-capture-select" onchange="selectDeviceCapture(this.value)"><option value="">Choose a persisted capture</option>${captureImports.map(x=>`<option value="${esc(x.id)}" ${x.id===captureStationCaptureId?'selected':''}>${esc(x.filename)} · ${esc(x.imported_at)}</option>`).join('')}</select></label><div class="table-wrap"><table class="table"><thead><tr><th>Observed station MAC</th><th>Management frame</th><th>Observed at</th><th>Capture</th><th>Associated AP</th></tr></thead><tbody>${captureStationRows.map(x=>`<tr><td class="mono">${esc(x.station_mac)}</td><td>${esc(x.frame_type)}</td><td>${esc(x.timestamp||'Not reported')}</td><td>${esc(x.source_capture)}</td><td>${esc(x.associated_bssid||'Not established')}</td></tr>`).join('')||'<tr><td colspan="5">Select a persisted capture containing supported management frames.</td></tr>'}</tbody></table></div></div></div>
 <div id="device-observation-inspector" class="panel" style="margin-top:14px"><div class="panel-head"><b>Observation detail</b></div><div class="panel-body muted">Select an observation row to inspect its original source and timestamp.</div></div>
 <div class="panel" style="margin-top:14px"><div class="panel-head"><b>Source-specific observation history</b></div><div class="panel-body table-wrap"><table class="table"><thead><tr><th>Source</th><th>Method</th><th>Interface</th><th>Count</th><th>First observed</th><th>Last observed</th><th>Data class</th></tr></thead><tbody>${histRows||'<tr><td colspan="7">No persisted observations yet.</td></tr>'}</tbody></table></div></div><div class="notice" style="margin-top:14px">Ordinary scans and the local neighbor table do not reveal every client associated with nearby access points. Wireless association requires AP telemetry or supported packet capture.</div></div>`
}
function inspectDeviceObservation(source,index){const list=deviceRecords.filter(x=>x.source===(source==='neighbor'?'OS neighbor cache':'Authorized ICMP echo')),selected=list[index];if(!selected)return;const d=selected.record,corroborating=deviceRecords.filter(x=>x.source!==selected.source&&x.record.ip&&x.record.ip===d.ip);const box=$('#device-observation-inspector');if(box)box.innerHTML=`<div class="panel-head"><b>Observation detail · ${esc(selected.source)}</b><span>${badge(d.status)}</span></div><div class="panel-body"><div class="kpi">IP <b class="mono">${esc(d.ip)}</b></div><div class="kpi">Observed at <b>${esc(d.observed_at||'Not reported')}</b></div><div class="kpi">Matching identifier in separate source records <b>${corroborating.length}</b></div><pre class="code">${esc(JSON.stringify(d,null,2))}</pre><div class="notice">Matching IPs are cross-referenced only. Source, status, and timestamp remain separate observations.</div></div>`}
function renderDeviceScanStatus(j){return `${esc(j.status)} · ${esc(j.scope)} · ${j.checked}/${j.total} probed · ${j.results?.length||0} ICMP responders${j.error?' · '+esc(j.error):''}${j.limitations?.length?`<div>${esc(j.limitations.join(' '))}</div>`:''}`}
async function startDeviceDiscovery(){if(!$('#device-scan-authorized')?.checked){toast('Confirm authorization before scanning');return}try{activeDeviceResults=[];deviceScanJob=await api('start_device_discovery',true);await render();startDeviceScanPolling()}catch(e){toast(e.message||String(e))}}
async function cancelDeviceDiscovery(){if(!deviceScanJob?.id)return;try{await api('cancel_device_discovery',deviceScanJob.id);toast('Cancellation requested')}catch(e){toast(e.message||String(e))}}
let activeDeviceResults=[],deviceScanJob=null,deviceScanTimer=null,deviceRecords=[];
let captureStationCaptureId='',captureStationRows=[],captureStationRowsLoaded=false;
async function selectDeviceCapture(id){captureStationCaptureId=id;captureStationRows=[];captureStationRowsLoaded=!id;if(id){try{const item=await api('capture_analysis',id);captureStationRows=item.analysis?.station_observations||[]}catch(e){toast(e.message||String(e))}captureStationRowsLoaded=true}if(state.page==='devices')await render()}
function startDeviceScanPolling(){if(deviceScanTimer)clearInterval(deviceScanTimer);if(deviceScanJob?.status!=='running')return;deviceScanTimer=setInterval(async()=>{try{deviceScanJob=await api('device_discovery_status',deviceScanJob.id);activeDeviceResults=deviceScanJob?.results||[];const box=$('#device-scan-status');if(box)box.innerHTML=renderDeviceScanStatus(deviceScanJob);if(deviceScanJob?.status!=='running'){clearInterval(deviceScanTimer);deviceScanTimer=null;if(state.page==='devices')await render()}}catch(e){clearInterval(deviceScanTimer);deviceScanTimer=null;toast(`Discovery status unavailable: ${e.message||e}`)}},700)}
function renderTestResult(r){
 if(!r)return '';
 const isNmap=r.test==='nmap_scan'||Array.isArray(r.open_ports);
 const ports=Array.isArray(r.open_ports)?r.open_ports:[];
 const status=(r.status||'unknown').toLowerCase();
 const heading=status==='completed'?'Test completed':status==='failed'?'Test failed':status==='blocked'?'Test blocked':'Test result';
 const summary=r.summary||r.error||'The test returned no summary.';
 const portRows=ports.map(p=>`<tr><td><b>${esc(p.port??'—')}</b></td><td>${esc((p.protocol||'tcp').toUpperCase())}</td><td>${badge(p.state||'open')}</td><td>${esc(p.service||'Unknown')}</td><td>${esc(p.product||'')}${p.version?` ${esc(p.version)}`:''}</td></tr>`).join('');
 return `<section class="panel test-result-panel" aria-live="polite"><div class="panel-head"><b>${esc(heading)}</b>${badge(status)}</div><div class="panel-body"><p class="test-result-summary">${esc(summary)}</p>${isNmap?`<div class="grid g3 test-result-kpis"><div class="card"><div class="label">Hosts scanned</div><div class="metric">${Number(r.host_count)||0}</div></div><div class="card"><div class="label">Open TCP ports</div><div class="metric">${ports.length}</div></div><div class="card"><div class="label">Nmap version</div><div class="metric" style="font-size:17px">${esc(r.nmap_version||'Not reported')}</div></div></div><h3 class="test-result-heading">Discovered services</h3><div class="table-wrap"><table class="table"><thead><tr><th>Port</th><th>Protocol</th><th>State</th><th>Service</th><th>Product / version</th></tr></thead><tbody>${portRows||'<tr><td colspan="5">No open ports were reported by this scan.</td></tr>'}</tbody></table></div>`:''}<div class="test-result-meta"><span>Execution ID: <b>${esc(r.execution_id||'Not returned')}</b></span><span>Evidence: <b>${esc(r.evidence_id||'Not recorded')}</b></span></div>${r.error?`<div class="notice error-notice">${esc(r.error)}</div>`:''}</div></section>`;
}
async function tests(){if(!state.aid)return `<div class="notice">Create or open an assessment first. <button class="ghost" onclick="go('assessments')">Open assessments</button></div>`;const data=await api('test_catalog',state.aid),st=await api('assessment',state.aid);return `<div class="panel"><div class="panel-head"><b>Security test catalog</b><span class="muted">Assessment: ${esc(st.assessment.name)} · ${data.catalog_size} tests</span></div><div class="panel-body table-wrap"><table class="table"><thead><tr><th>Test</th><th>Purpose</th><th>Path</th><th>Status</th><th></th></tr></thead><tbody>${data.groups.flatMap(g=>g.tests.map(t=>`<tr><td><b>${esc(t.name)}</b><div class="muted">${esc(g.category)}</div></td><td>${esc(t.purpose)}</td><td>${badge(t.execution_path)}</td><td>${badge(state.runningTestId===t.id?'running':t.status)}<div class="muted">${state.runningTestId===t.id?'Executing locally…':esc(t.status_reason||'')}</div></td><td><button class="ghost" id="run-test-${esc(t.id)}" onclick="runOne('${esc(t.id)}')" ${(t.blocked||state.runningTestId)?'disabled':''}>${state.runningTestId===t.id?'Running…':'Run'}</button></td></tr>`)).join('')}</tbody></table></div></div>${state.runningTestId?`<div class="panel test-running-panel" aria-live="polite"><div class="panel-body"><div class="row-actions"><span class="spinner"></span><b>Running ${esc(data.groups.flatMap(g=>g.tests).find(t=>t.id===state.runningTestId)?.name||'security test')}</b></div><div class="muted" style="margin-top:8px">WiFiSentinel is waiting for the local tool to finish and return its observations. Keep this page open.</div></div></div>`:''}${state.lastTestResult?renderTestResult(state.lastTestResult):''}`}
async function runOne(id){if(state.runningTestId)return;let config={};if(id==='port_assessment'){let host=prompt('In-scope IP address',(await api('wifi_discovery')).connected?await gatewayFromUI():'');if(!host)return;config.host=host}else if(id==='traceroute'){let host=prompt('In-scope host/IP',await gatewayFromUI());if(!host)return;config.host=host}else if(id==='nmap_scan'){let host=prompt('In-scope IP address','192.168.0.100');if(!host)return;config.host=host}
 state.runningTestId=id;state.lastTestResult=null;await render();
 try{const r=await api('run_test',state.aid,id,config);state.lastTestResult=r||{status:'error',error:'The backend returned no result.'};toast(r?.status==='completed'?'Test completed':(r?.error||r?.status||'Test finished'));}
 catch(e){state.lastTestResult={status:'failed',error:e?.message||String(e)};toast('Test failed. See the result details below.');}
 finally{state.runningTestId=null;if(state.page==='tests')await render();}
}
async function gatewayFromUI(){let w=await api('devices');let g=w.find(x=>x.is_gateway);return g?.ip||''}
async function execution(){if(!state.aid)return `<div class="notice">Open an assessment first.</div>`;let p=await api('preflight',state.aid),ev=await api('events',state.aid);return `<div class="grid g2"><div class="panel"><div class="panel-head"><b>Preflight</b><span>${p.ready?'<span class="ok">Ready</span>':'<span class="bad">Blocked checks present</span>'}</span></div><div class="panel-body">${p.checks.map(c=>`<div class="step"><div class="split"><b>${esc(c.label)}</b>${badge(c.status)}</div><div class="muted">${esc(c.detail)}</div></div>`).join('')}</div></div><div class="panel"><div class="panel-head"><b>Assessment execution</b></div><div class="panel-body"><div class="notice">Execution performs live Wi-Fi/ARP observations, wireless posture checks and research-dataset analysis. Connector-only tests are blocked until the connector is available.</div><button class="primary" style="margin-top:12px" onclick="startExecution()" ${p.ready?'':'disabled'}>Execute assessment</button><button class="ghost" style="margin-left:6px" onclick="go('tests')">Security tests</button><div id="execbox" style="margin-top:15px"></div></div></div></div><div class="panel" style="margin-top:14px"><div class="panel-head"><b>Assessment timeline</b></div><div class="panel-body">${ev.map(x=>`<div class="step"><div class="split"><b>${esc(x.event_type)}</b><span class="muted">${esc(x.created_at)}</span></div><div class="muted">${esc(x.message)}</div></div>`).join('')||'<div class="empty">No execution events yet.</div>'}</div></div>`}
async function startExecution(){const aid=state.aid,token=++executionSeq;try{let r=await api('execute_assessment',aid);if(token!==executionSeq||aid!==state.aid)return;if(r.blocked){toast(r.reason);return}if(r.error){toast(r.error);return}state.exid=r.execution_id;pollExecution(token,aid,r.execution_id)}catch(e){if(token===executionSeq)toast(e.message||String(e))}}
async function pollExecution(token,aid,exid){if(token!==executionSeq||aid!==state.aid)return;try{let e=await api('execution',exid);if(token!==executionSeq||aid!==state.aid)return;let box=$('#execbox');if(box)box.innerHTML=`<div class="label">${esc(e.stage)}</div><div class="progress"><i style="width:${e.progress}%"></i></div><div class="muted" style="margin-top:6px">${e.progress}% · ${esc(e.status)}</div>`;if(e.status==='running')setTimeout(()=>pollExecution(token,aid,exid),800);else{toast('Assessment '+e.status);setTimeout(()=>{if(token===executionSeq&&aid===state.aid)render()},300)}}catch(e){if(token===executionSeq)toast(`Execution status unavailable: ${e.message||e}`)}}
async function findings(){if(!state.aid)return '<div class="notice">Open an assessment first.</div>';let fs=await api('findings',state.aid);return `<div class="panel"><div class="panel-head"><b>Findings</b><span class="muted">Only persisted observations are shown.</span></div><div class="panel-body table-wrap"><table class="table"><thead><tr><th>Severity</th><th>Finding</th><th>Source</th><th>Description</th><th>Status</th><th>AI</th></tr></thead><tbody>${fs.map(f=>`<tr><td>${badge(f.severity)}</td><td><b>${esc(f.title)}</b><div class="muted">${esc(f.recommendation)}</div></td><td>${esc(f.source_test)}</td><td>${esc(f.description)}</td><td>${esc(f.status)}</td><td><button class="ghost" onclick="runAI('finding:${f.id}')">Review</button></td></tr>`).join('')}</tbody></table>${fs.length?'':'<div class="empty">No findings have been generated yet. Execute an authorized assessment or run a security test.</div>'}</div></div>`}
async function evidence(){if(!state.aid)return '<div class="notice">Open an assessment first.</div>';let es=await api('evidence',state.aid);return `<div class="panel"><div class="panel-head"><b>Evidence</b><span class="muted">Live observations and research evidence are labeled separately.</span></div><div class="panel-body">${es.map(e=>`<div class="step"><div class="split"><div><b>${esc(e.label||e.type)}</b><div class="muted">${esc(e.type)} · ${esc(e.source)} · ${esc(e.data_class||'unclassified')}</div></div><button class="ghost" onclick="showEvidence('${esc(e.id)}')">View evidence</button></div><div class="muted" style="margin-top:6px">${esc(e.created_at)} · ${Number(e.content_length||0).toLocaleString()} characters</div><div id="evidence-${esc(e.id)}"></div></div>`).join('')||'<div class="empty">No evidence collected yet.</div>'}</div></div>`}
async function showEvidence(eid){const host=$(`#evidence-${CSS.escape(eid)}`);if(!host)return;host.textContent='Loading evidence…';try{const item=await api('evidence_item',state.aid,eid);if(!item){host.textContent='Evidence item not found.';return}const body=typeof item.content==='string'?item.content:JSON.stringify(item.content,null,2);host.innerHTML=`<pre class="code evidence-body">${esc(body)}</pre>`}catch(e){host.textContent=`Evidence unavailable: ${e.message||e}`}}
async function dataset(){let s=await api('dataset_summary'),d=await api('dataset_detection',10),a=await api('dataset_analysis');return `<div class="grid g4"><div class="card"><div class="label">Valid records</div><div class="metric">${s.records.toLocaleString()}</div></div><div class="card"><div class="label">Attack label</div><div class="metric">${(s.labels.attack||0).toLocaleString()}</div></div><div class="card"><div class="label">Normal label</div><div class="metric">${(s.labels.normal||0).toLocaleString()}</div></div><div class="card"><div class="label">Research IDs</div><div class="metric">${s.devices}</div></div></div><div class="panel" style="margin-top:14px"><div class="panel-head"><b>Dataset provenance and parsing</b><span>${badge(s.parsing_status||'unknown')}</span></div><div class="panel-body"><div class="kpi">Source file <b>${esc(s.file||'Unavailable')}</b></div><div class="kpi">Rows seen <b>${Number(s.rows_seen||0).toLocaleString()}</b></div><div class="kpi">Malformed or excluded rows <b>${Number(s.discarded_rows||0).toLocaleString()}</b></div><div class="kpi">Last processed <b>${esc(s.last_processed_at||'Not processed')}</b></div>${s.schema_errors?.length?`<div class="notice">Required columns missing: ${esc(s.schema_errors.join(', '))}</div>`:''}<p class="muted">Dataset records are research evidence, never live Wi-Fi observations or local device inventory.</p></div></div><div class="grid g2" style="margin-top:14px"><div class="panel"><div class="panel-head"><b>Dataset structure</b><button class="ghost" onclick="runAI('dataset')">AI analysis</button></div><div class="panel-body"><div class="kpi">Start <b>${esc(s.start)}</b></div><div class="kpi">End <b>${esc(s.end)}</b></div><div class="kpi">Associated <b>${s.associations.associated||0}</b></div><div class="kpi">Disassociated <b>${s.associations.disassociated||0}</b></div></div></div><div class="panel"><div class="panel-head"><b>Detection rule</b></div><div class="panel-body"><div class="notice">${d.count} research windows meet the default threshold of ≥10 disassociation events with ≥50% disassociation ratio in 60 seconds. This is corpus analysis, not a live alert.</div><div style="margin-top:12px" class="table-wrap"><table class="table"><thead><tr><th>Research ID</th><th>Window</th><th>Disassoc.</th><th>Label</th></tr></thead><tbody>${d.events.slice(0,20).map(x=>`<tr><td>${esc(x.device)}</td><td>${esc(x.window)}</td><td>${x.disassociations}</td><td>${badge(x.attack_label)}</td></tr>`).join('')}</tbody></table></div></div></div></div><div class="panel" style="margin-top:14px"><div class="panel-head"><b>Per-device research analysis</b></div><div class="panel-body table-wrap"><table class="table"><thead><tr><th>Research ID</th><th>Events</th><th>Attack</th><th>Normal</th><th>Disassociation ratio</th></tr></thead><tbody>${a.devices.map(x=>`<tr><td>${esc(x.device)}</td><td>${x.events}</td><td>${x.attack}</td><td>${x.normal}</td><td>${(x.disassociation_ratio*100).toFixed(1)}%</td></tr>`).join('')}</tbody></table></div></div>`}
async function reports(){if(!state.aid)return '<div class="notice">Open an assessment first.</div>';return `<div class="grid g3"><div class="card"><b>AI report</b><p class="muted">Generate an evidence-grounded executive summary from the current assessment.</p><button class="primary" onclick="runAI('report')">Generate AI report</button></div><div class="card"><b>JSON export</b><p class="muted">Full assessment record, including observations, findings, executions, evidence and analysis history.</p><button class="ghost" onclick="downloadReport('json')">Export JSON</button></div><div class="card"><b>CSV export</b><p class="muted">Persisted findings with spreadsheet-formula protection.</p><button class="ghost" onclick="downloadReport('csv')">Export CSV</button></div><div class="card"><b>PDF report</b><p class="muted">Paginated assessment report with scope, coverage, posture, observations, evidence and limitations.</p><button class="primary" onclick="downloadReport('pdf')">Generate PDF</button></div><div class="notice">Exports are written to the project reports folder with unique timestamped names.</div></div>`}
async function downloadReport(kind){let r=await api(kind==='json'?'export_json':kind==='csv'?'export_csv':'export_pdf',state.aid);toast(typeof r==='string'?r:(r.error||'Export failed'))}
function aiRender(obj){if(!obj||typeof obj!=='object')return `<div class="code">${esc(obj)}</div>`;let out='';for(const [k,v] of Object.entries(obj)){let label=k.replace(/_/g,' ').replace(/\b\w/g,m=>m.toUpperCase());if(Array.isArray(v))out+=`<div class="ai-section"><div class="label">${esc(label)}</div><ul>${v.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`;else out+=`<div class="ai-section"><div class="label">${esc(label)}</div><p>${esc(v)}</p></div>`}return out}
async function aiAnalysis(){let s=await api('ai_status'),hist=state.aiKind==='dataset'?await api('ai_history',null,'dataset'):await api('ai_history',state.aid);return `<div class="hero"><div class="split"><div><h2>Evidence-grounded AI analysis</h2><div class="muted">OpenAI interprets persisted observations. Research-dataset analysis is stored separately from assessment evidence.</div></div><div>${s.configured?'<span class="ok">API configured</span>':'<span class="bad">API key required</span>'}</div></div></div><div class="notice" style="margin-bottom:14px">When you run an analysis, the selected assessment evidence or research statistics are sent to the OpenAI API. Only analyze data approved for that service.</div><div class="grid g3"><div class="card"><b>Dataset analysis</b><p class="muted">Behavioral signals, device patterns, anomaly windows and dataset limitations.</p><button class="primary" onclick="runAI('dataset')" ${s.configured?'':'disabled'}>Analyze dataset</button></div><div class="card"><b>Assessment review</b><p class="muted">Synthesize live observations, findings, evidence and coverage gaps.</p><button class="primary" onclick="runAI('assessment')" ${state.aid&&s.configured?'':'disabled'}>Review assessment</button></div><div class="card"><b>Security posture</b><p class="muted">Summarize strengths, risk themes, evidence gaps and defensive priorities.</p><button class="primary" onclick="runAI('posture')" ${state.aid&&s.configured?'':'disabled'}>Review posture</button></div></div><div class="panel" style="margin-top:14px"><div class="panel-head"><b>${state.aiKind==='dataset'?'Research dataset history':'Assessment analysis history'}</b><span class="muted">${hist.length} saved result${hist.length===1?'':'s'}</span></div><div class="panel-body">${hist.length?hist.map(x=>`<div class="step"><div class="split"><b>${esc(x.kind)}</b><span class="muted">${esc(x.created_at)} · ${esc(x.model)}</span></div>${aiRender(x.content)}</div>`).join(''):'<div class="empty">No AI analysis has been generated yet.</div>'}</div></div>`}
async function runAI(kind){if(!state.aiDisclosureConfirmed){if(!confirm('This analysis sends the selected assessment evidence or research summary to OpenAI for processing. Continue?'))return;state.aiDisclosureConfirmed=true}toast('Running AI analysis…');try{let r=await api('ai_analyze',kind,state.aid);if(!r.ok){toast(r.error||'AI analysis failed');return}toast('AI analysis completed');state.aiKind=kind==='dataset'?'dataset':'assessment';state.page='ai';await render();}catch(e){toast(e.message||String(e))}}
async function settings(){const [s,a,sys,caps]=await Promise.all([api('settings'),api('ai_status'),api('system_info'),api('platform_capabilities')]);state.theme=s.theme||state.theme;applyTheme(state.theme);return `<div class="grid g2"><div class="panel"><div class="panel-head"><b>Appearance</b></div><div class="panel-body form"><div class="field"><label for="theme-select">Theme</label><select id="theme-select" onchange="setTheme(this.value)"><option value="dark" ${state.theme==='dark'?'selected':''}>Dark</option><option value="light" ${state.theme==='light'?'selected':''}>Light</option><option value="matrix" ${state.theme==='matrix'?'selected':''}>Green Matrix</option><option value="retro" ${state.theme==='retro'?'selected':''}>Retro Classic</option></select></div><div class="check"><label><input id="matrix-rain-enabled" type="checkbox" ${matrixPrefs.enabled?'checked':''}> Animated Matrix rain</label></div><div class="field"><label for="matrix-intensity">Matrix rain intensity</label><select id="matrix-intensity"><option value="low" ${matrixPrefs.intensity==='low'?'selected':''}>Low</option><option value="medium" ${matrixPrefs.intensity==='medium'?'selected':''}>Medium</option><option value="high" ${matrixPrefs.intensity==='high'?'selected':''}>High</option></select></div><div class="muted">Animation is decorative, pauses in the background, and turns off when reduced motion is requested.</div></div></div><div class="panel"><div class="panel-head"><b>Kali connector</b></div><div class="panel-body form"><div class="field"><label>Connector URL</label><input id="curl" value="${esc(s.connector_url)}" placeholder="http://kali-host:8787"></div><div class="row-actions"><button class="primary" onclick="saveSettings()">Save connector</button><button class="ghost" onclick="checkConnector()">Check health</button></div><div id="connector-health" class="notice">${s.connector_url?'Configured; health has not been checked.':'Not configured.'}</div></div></div></div><div class="grid g2" style="margin-top:14px"><div class="panel"><div class="panel-head"><b>Platform capabilities</b><span class="muted">${esc(caps.os)} · ${esc(caps.architecture)}</span></div><div class="panel-body table-wrap"><table class="table"><thead><tr><th>Capability</th><th>Status</th><th>Details</th></tr></thead><tbody>${caps.capabilities.map(x=>`<tr><td><b>${esc(x.name)}</b></td><td>${badge(x.status)}</td><td>${esc(x.detail)}</td></tr>`).join('')}</tbody></table><div class="muted" style="margin-top:10px">Interfaces: ${caps.interfaces.length?caps.interfaces.map(i=>`${esc(i.name)}${i.description?' · '+esc(i.description):''} (${esc(i.state||'state unavailable')})`).join(' · '):'Not exposed by the operating system or permission required.'}</div></div></div><div class="panel"><div class="panel-head"><b>OpenAI</b></div><div class="panel-body"><div class="kpi"><span>Provider</span><b>${esc(a.provider)}</b></div><div class="kpi"><span>Model</span><b class="mono">${esc(a.model)}</b></div><div class="kpi"><span>Status</span><b>${a.configured?'<span class="ok">Configured</span>':'<span class="bad">Not configured</span>'}</b></div><p class="muted">Configure <span class="mono">OPENAI_API_KEY</span> in <span class="mono">.env</span>. Secrets remain outside SQLite.</p></div></div></div><div class="panel" style="margin-top:14px"><div class="panel-head"><b>System</b></div><div class="panel-body"><div class="muted">Python ${esc(caps.python)} · ${esc(caps.os_version)} · Data: ${esc(sys.data_dir)} · Reports: ${esc(sys.reports_dir)}</div><pre class="code">${esc(JSON.stringify(sys,null,2))}</pre></div></div>`}
async function checkConnector(){const box=$('#connector-health');if(box)box.textContent='Checking connector health…';try{const h=await api('connector_health');if(box)box.textContent=`${h.status}${h.error?' · '+h.error:''}`}catch(e){if(box)box.textContent=`Health check failed: ${e.message||e}`}}
async function saveSettings(){await api('set_settings',{connector_url:$('#curl').value});toast('Settings saved');await checkConnector()}
const themeOrder=['dark','light','matrix','retro'];
function applyTheme(theme){state.theme=themeOrder.includes(theme)?theme:'dark';document.body.classList.remove('light','theme-matrix','theme-retro');if(state.theme==='light')document.body.classList.add('light');if(state.theme==='matrix')document.body.classList.add('theme-matrix');if(state.theme==='retro')document.body.classList.add('theme-retro');const names={dark:'Light',light:'Green Matrix',matrix:'Retro Classic',retro:'Dark'};const button=$('#theme');if(button)button.textContent=names[state.theme];syncMatrixRain()}
const matrixMotion=window.matchMedia?.('(prefers-reduced-motion: reduce)');const readPref=(key,fallback)=>{try{return localStorage.getItem(key)??fallback}catch(_){return fallback}},writePref=(key,value)=>{try{localStorage.setItem(key,value)}catch(_){}};let matrixPrefs={enabled:readPref('ws-matrix-rain','on')!=='off',intensity:readPref('ws-matrix-intensity','medium')},matrixFrame=null,matrixLast=0,matrixColumns=[];
function bindMatrixControls(){const enabled=$('#matrix-rain-enabled'),intensity=$('#matrix-intensity');if(enabled)enabled.onchange=()=>{matrixPrefs.enabled=enabled.checked;writePref('ws-matrix-rain',enabled.checked?'on':'off');syncMatrixRain()};if(intensity)intensity.onchange=()=>{matrixPrefs.intensity=intensity.value;writePref('ws-matrix-intensity',intensity.value);syncMatrixRain()}}
function syncMatrixRain(){const canvas=$('#matrix-rain');if(!canvas)return;const reduce=!!matrixMotion?.matches,active=state.theme==='matrix'&&matrixPrefs.enabled&&!reduce&&!document.hidden;canvas.style.display=active?'block':'none';canvas.style.opacity=matrixPrefs.intensity==='high'?'.25':matrixPrefs.intensity==='low'?'.09':'.16';if(active&&!matrixFrame){resizeMatrixCanvas();matrixFrame=requestAnimationFrame(drawMatrixRain)}else if(!active&&matrixFrame){cancelAnimationFrame(matrixFrame);matrixFrame=null}}
function resizeMatrixCanvas(){const canvas=$('#matrix-rain'),ctx=canvas?.getContext('2d');if(!canvas||!ctx)return;const width=window.innerWidth,height=window.innerHeight;canvas.width=Math.min(width,1920);canvas.height=Math.min(height,1200);const font=15;ctx.font=`${font}px monospace`;matrixColumns=Array.from({length:Math.ceil(canvas.width/(font*1.15))},()=>Math.random()*-50);canvas.dataset.font=String(font)}
function drawMatrixRain(now){const canvas=$('#matrix-rain'),ctx=canvas?.getContext('2d');if(!canvas||!ctx||state.theme!=='matrix'||!matrixPrefs.enabled||matrixMotion?.matches||document.hidden){matrixFrame=null;return}matrixFrame=requestAnimationFrame(drawMatrixRain);if(now-matrixLast<55)return;matrixLast=now;const font=Number(canvas.dataset.font)||15;ctx.fillStyle='rgba(3,8,5,.12)';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.font=`${font}px monospace`;for(let i=0;i<matrixColumns.length;i++){const y=matrixColumns[i]*font;ctx.fillStyle=i%8===0?'rgba(179,255,190,.82)':'rgba(48,190,78,.55)';ctx.fillText('01ﾊﾐｳｼﾄﾈﾆｻﾎﾓﾘ',i*font*1.15,y);if(y>canvas.height&&Math.random()>.98)matrixColumns[i]=0;else matrixColumns[i]+=.55+Math.random()*.7}}
window.addEventListener('resize',()=>{if(state.theme==='matrix'&&matrixPrefs.enabled&&!matrixMotion?.matches)resizeMatrixCanvas()});document.addEventListener('visibilitychange',()=>{syncMatrixRain();if(document.hidden)clearWifiCredential()});matrixMotion?.addEventListener?.('change',syncMatrixRain);
function setTheme(theme){applyTheme(theme);if(B)api('set_settings',{theme:state.theme}).catch(e=>toast(e.message||String(e)))}
function toggleTheme(){const i=themeOrder.indexOf(state.theme);setTheme(themeOrder[(i+1)%themeOrder.length])}
async function tools(){return `<div class="hero"><h2>Tool capability matrix</h2><div class="muted">Detection is separate from integration. An executable or connector inventory does not mean WiFiSentinel has executed or validated that tool.</div></div><div class="panel"><div class="panel-head"><b>Local and Kali tool inventory</b><button class="primary" onclick="inspectTools()">Inspect available tools</button></div><div id="tool-matrix" class="panel-body"><div class="empty">Run a bounded local version check and, if configured, request the connector's declared tool inventory.</div></div></div><div class="notice" style="margin-top:14px">This release does not invoke local Nmap, Kismet, TShark, tcpdump, Aircrack-ng, or iw from the assessment catalog. Connector-backed operations require the documented API and return persisted results only when the endpoint responds successfully.</div>`}
async function inspectTools(){const host=$('#tool-matrix');if(!host)return;host.innerHTML='<div class="loading-card"><span class="spinner"></span><b>Checking executable versions and connector inventory</b></div>';try{const matrix=await api('tool_matrix'),remote=matrix.connector.data,remoteTools=Array.isArray(remote?.tools)?remote.tools:(Array.isArray(remote)?remote:[]),kaliWifi=matrix.kali_wireless||{},wifiData=kaliWifi.data||{},interfaces=wifiData.interfaces||[];const kismet=matrix.kismet_observations||{},kd=kismet.data||{},apRows=kd.access_points||[],clientRows=kd.clients||[],kismetHtml=`<h3 style="margin-top:18px">Kismet passive observations</h3><div class="muted">Source: ${esc(kd.source||'Kismet REST API')} · ${esc(kd.observed_at||'Not observed')}</div>${kismet.status==='HEALTHY'?`<div class="kpi">AP observations <b>${apRows.length}${kd.access_points_truncated?' (limited)':''}</b></div><div class="kpi">Client observations <b>${clientRows.length}</b></div><div class="table-wrap"><table class="table"><thead><tr><th>Observed AP name</th><th>BSSID</th><th>Channel</th><th>Source evidence</th></tr></thead><tbody>${apRows.map(x=>`<tr><td>${esc(x['kismet.device.base.name']||'Not reported')}</td><td class="mono">${esc(x['kismet.device.base.macaddr']||'Not reported')}</td><td>${esc(x['kismet.device.base.channel']||'Not reported')}</td><td>Kismet AP view</td></tr>`).join('')||'<tr><td colspan="4">No AP records returned by Kismet.</td></tr>'}</tbody></table></div><div class="muted">${esc((kd.limitations||[]).join(' '))}</div><div class="muted">Permissions: ${esc(kd.permission_status||'Not reported')} · Last packet: ${esc(kd.last_packet_at||kd.last_packet_note||'Not reported by Kismet')}</div><details><summary>Raw Kismet AP records (${apRows.length})</summary><pre class="code">${esc(JSON.stringify(apRows,null,2))}</pre></details><details><summary>Raw Kismet datasource records (${(kd.datasources||[]).length})</summary><pre class="code">${esc(JSON.stringify(kd.datasources||[],null,2))}</pre></details><details><summary>Client observation records (${clientRows.length})</summary><pre class="code">${esc(JSON.stringify(clientRows,null,2))}</pre></details><div class="muted">Raw fields retain source timestamps and signal metadata when Kismet returns them; absent values are not filled in.</div>`:`<div class="empty">${esc(kismet.detail||kd.error||'Configure Kismet on Kali; this source remains unavailable.')}</div>`}<div class="muted">Kismet association records are source-labelled observations. They are not merged with OS neighbor-cache rows or interpreted as confirmed current identities.</div>`;const kaliWifiHtml=`<h3 style="margin-top:18px">Kali wireless interfaces and capture capability</h3><div class="muted">Source: ${esc(wifiData.source||'Authenticated connector capability query')} · ${esc(wifiData.observed_at||'Not observed')}</div>${interfaces.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Interface</th><th>PHY</th><th>Driver</th><th>Current mode</th><th>Supported modes</th><th>Monitor support</th><th>Supported bands / channels</th><th>Capture state</th><th>Permissions / last packet</th></tr></thead><tbody>${interfaces.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.phy||'Not reported')}</td><td>${esc(x.driver||'Not exposed')}</td><td>${esc(x.interface_type||'Not reported')}</td><td>${esc((x.supported_modes||[]).join(', ')||'Not reported')}</td><td>${x.monitor_mode_supported===true?'Supported by reported PHY':x.monitor_mode_supported===false?'Not reported by driver':'Unknown'}</td><td>${esc((x.supported_bands_ghz||[]).join(', ')||'Not reported')} GHz / ${esc((x.supported_channels||[]).join(', ')||'Not reported')}</td><td>${esc(x.current_capture_state||'Not reported')}</td><td>${esc(x.permission_status||'Not reported')} · ${esc(x.last_packet_at||x.last_packet_note||'Last packet time not reported')}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">${esc(wifiData.error||kaliWifi.detail||'No wireless interface was reported. An installed iw/nmcli tool alone does not prove radio hardware is passed through.')}</div>`}<div class="muted">${esc((wifiData.limitations||[]).join(' '))}</div>`;host.innerHTML=`<h3>Local desktop tools · ${esc(matrix.os||'this computer')}</h3><div class="table-wrap"><table class="table"><thead><tr><th>Tool</th><th>Status</th><th>Version</th><th>Purpose / prerequisites</th><th>Detection detail</th></tr></thead><tbody>${matrix.local.map(x=>`<tr><td><b>${esc(x.name)}</b><div class="muted">${esc(x.executable)}</div></td><td>${badge(x.status)}</td><td>${esc(x.version||'Unavailable')}</td><td>${esc(x.purpose)}<div class="muted">${esc(x.prerequisites)}</div></td><td>${esc(x.detail)}</td></tr>`).join('')}</tbody></table></div><h3 style="margin-top:18px">Remote Kali tools</h3><div class="kpi">Connector status <b>${badge(matrix.connector.status)}</b></div><p class="muted">${esc(matrix.connector.detail)}</p>${remoteTools.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Tool</th><th>Installed status</th><th>Version</th><th>Invoked by connector</th><th>Purpose</th></tr></thead><tbody>${remoteTools.map(x=>`<tr><td><b>${esc(x.name||'Unknown')}</b></td><td>${badge(x.status||'UNKNOWN')}</td><td>${esc(x.version||'Not reported')}</td><td>${x.invoked_by_connector?'Yes':'No'}</td><td>${esc(x.purpose||'Not reported')}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">No authenticated Kali tool inventory is available.</div>`}${kaliWifiHtml}${kismetHtml}<p class="muted">An installed tool is not necessarily invoked by WiFiSentinel. Unsupported connector operations remain unavailable even when related tools are installed.</p>`}catch(e){host.innerHTML=`<div class="notice error-notice">Tool inspection failed: ${esc(e.message||e)}</div>`}}
async function captureReview(){
 const prior=await api('capture_history'),selected=state.captureSelection;
 const rows=prior.map(x=>`<tr><td>${esc(x.filename)}</td><td>${esc(x.capture_format)}</td><td>${Number(x.size_bytes).toLocaleString()} bytes</td><td class="mono">${esc(x.source_sha256)}</td><td>${esc(x.imported_at)}</td><td class="mono">${esc(x.evidence_id)}</td><td><button class="ghost" onclick="openCapture('${esc(x.id)}')">Open</button></td></tr>`).join('');
 const selection=selected?`<div class="panel-body"><div class="kpi">Selected file <b>${esc(selected.filename)}</b></div><div class="kpi">Size <b>${Number(selected.size_bytes).toLocaleString()} bytes</b> · maximum ${Math.floor(selected.maximum_size_bytes/1048576)} MiB</div><div class="kpi">Extension <b>${esc(selected.format_from_extension.toUpperCase())}</b> · signature and packet structure are validated during analysis.</div><label>Optional SSID or BSSID scope<input id="capture-scope" placeholder="Leave blank for capture-wide metadata; wireless identities stay unscoped"></label><label class="check"><input id="capture-authorized" type="checkbox"> I am authorized to analyze this file and its contents.</label><div class="row-actions"><button class="primary" onclick="analyzeCapture()">Analyze capture</button><button class="ghost" onclick="cancelCaptureSelection()">Cancel</button></div></div>`:'<div class="panel-body muted">Choose a local PCAP or PCAPNG file. Upload works without a prior network scan or selected access point.</div>';
 return `<div class="hero"><h2>Offline PCAP / PCAPNG review</h2><div class="muted">Select an existing capture for bounded, offline analysis. No packets are sent. Authorization is required before analysis; optional SSID/BSSID scope filters wireless identities.</div></div><div class="grid g2"><div class="panel"><div class="panel-head"><b>Capture upload</b><button class="primary" onclick="selectCaptureFile()">Upload capture</button></div>${selection}</div><div class="panel"><div class="panel-head"><b>Interpretation boundaries</b></div><div class="panel-body"><ul><li>A candidate WPA exchange is a packet-pattern observation, not proof of a usable key exchange or vulnerability.</li><li>PMF negotiation/enforcement stays unknown unless the capture contains relevant evidence.</li><li>Application payloads are not extracted. Evidence is stored locally with SHA-256 integrity.</li><li>Live capture and radio transmission are not implemented; this page analyzes an existing file.</li></ul></div></div></div><div id="capture-result" class="panel" style="margin-top:14px;display:none"></div><div class="panel" style="margin-top:14px"><div class="panel-head"><b>Previously imported captures</b></div><div class="table-wrap"><table class="table"><thead><tr><th>File</th><th>Format</th><th>Size</th><th>SHA-256</th><th>Imported</th><th>Evidence</th><th></th></tr></thead><tbody>${rows||'<tr><td colspan="7">No capture imports have been persisted.</td></tr>'}</tbody></table></div></div>`
}
async function confirmNetworkCaptureAuthorization(){if(!$('#capture-authorized')?.checked){toast('Confirm that you are authorized for this AP capture scope');return}try{await api('confirm_network_capture_authorization',state.aid,true);await render()}catch(e){toast(e.message||String(e))}}
async function selectCaptureFile(){try{const result=await api('select_capture');if(result.cancelled)return;if(!result.ok)throw Error(result.error||'Capture selection failed.');state.captureSelection=result;await render()}catch(e){toast(e.message||String(e))}}
function renderCaptureStations(rows){return `<h3>Station identifiers observed in this capture</h3><div class="muted">Imported-capture evidence only. It does not show current presence or prove AP association.</div>${rows?.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Observed station MAC</th><th>Frame</th><th>Observed at</th><th>Capture</th></tr></thead><tbody>${rows.map(x=>`<tr><td class="mono">${esc(x.station_mac)}</td><td>${esc(x.frame_type)}</td><td>${esc(x.timestamp||'Not available')}</td><td>${esc(x.source_capture)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No supported station-identity management frames were present in this capture.</div>'}`}
async function openCapture(id){try{const x=await api('capture_analysis',id),r=x.analysis,box=$('#capture-result');if(box){box.style.display='block';box.innerHTML=`<div class="panel-head"><b>Persisted capture analysis</b><span class="mono">${esc(x.evidence_id)}</span></div><div class="panel-body"><div class="kpi">${esc(x.filename)} · SHA-256 <b class="mono">${esc(x.sha256)}</b></div><div class="kpi">Packets examined <b>${Number(r.packets_examined||0).toLocaleString()}</b></div>${renderCaptureStations(r.station_observations)}<pre class="code">${esc(JSON.stringify(r,null,2))}</pre></div>`;box.scrollIntoView({behavior:'smooth',block:'start'})}}catch(e){toast(e.message||String(e))}}
async function cancelCaptureSelection(){const selected=state.captureSelection;if(!selected)return;try{const result=await api('cancel_capture_selection',selected.selection_id);if(!result.cancelled)throw Error(result.error||'Could not cancel selection.');state.captureSelection=null;await render()}catch(e){toast(e.message||String(e))}}
async function analyzeCapture(){const selected=state.captureSelection,box=$('#capture-result');if(!selected)return toast('Choose a capture file first');if(box){box.style.display='block';box.innerHTML='<div class="loading-card"><span class="spinner"></span><div><b>Validating and analyzing locally</b><div id="capture-progress-text" class="muted">Preparing a bounded offline analysis.</div></div></div>'}try{
 if(!$('#capture-authorized')?.checked)throw Error('Confirm authorization before analysis.');const taskArgs=[selected.selection_id,true,$('#capture-scope')?.value||''];let taskDone=false;const task=api('analyze_capture_selection',...taskArgs);task.then(()=>taskDone=true,()=>taskDone=true);while(!taskDone){await new Promise(resolve=>setTimeout(resolve,400));let p;try{p=await api('capture_progress',selected.selection_id)}catch{continue}const text=$('#capture-progress-text');if(text)text.textContent=p.stage==='copying'?`Copying selected file: ${Number(p.bytes_copied||0).toLocaleString()} / ${Number(p.bytes_total||0).toLocaleString()} bytes`:p.stage==='parsing'?`Analyzed ${Number(p.packets_examined||0).toLocaleString()} packets so far; processing remains bounded by file and packet limits.`:p.stage==='complete'?'Analysis complete. Saving evidence locally.':p.stage==='failed'?p.error||'Analysis failed.':'Validating capture structure.'}
 const response=await task;if(!response.ok)throw Error(response.error||'Capture analysis failed.');state.captureSelection=null;const r=response.result;const pairText=JSON.stringify(r.exchange_pairs,null,2),protocolText=JSON.stringify(r.protocol_counts,null,2),wirelessText=JSON.stringify(r.wireless_observations,null,2);
 if(box)box.innerHTML=`<div class="panel-head"><b>${response.duplicate?'Existing capture import found':'Capture analysis persisted'}</b><span>${badge(r.candidate_exchanges?'Candidate exchange observed':'No candidate exchange observed')}</span></div><div class="panel-body"><div class="kpi">File <b>${esc(r.filename)}</b></div><div class="kpi">Format / size <b>${esc(r.capture_format.toUpperCase())} · ${Number(r.size_bytes).toLocaleString()} bytes</b></div><div class="kpi">SHA-256 <b class="mono">${esc(r.sha256)}</b></div><div class="kpi">Packets examined / link types <b>${r.packets_examined} / ${esc(r.linktypes.map(x=>x.name).join(', ')||'Not reported')}</b></div><div class="kpi">Captured / original frame size range <b>${esc(r.frame_size_min_bytes??'Not reported')}–${esc(r.frame_size_max_bytes??'Not reported')} / ${esc(r.wire_size_min_bytes??'Not reported')}–${esc(r.wire_size_max_bytes??'Not reported')} bytes</b></div><div class="kpi">First / last packet timestamp <b>${esc(r.first_packet_timestamp??'Not reported')} / ${esc(r.last_packet_timestamp??'Not reported')}</b></div><div class="kpi">Capture-wide wireless frames / in-scope EAPOL / SAE frames <b>${r.wireless_frames} / ${r.eapol_frames} / ${r.sae_authentication_frames}</b></div><div class="kpi">In-scope exchange pairs / endpoints <b>${r.exchange_pairs.length} / ${r.endpoint_count}</b></div><div class="kpi">Evidence ID <b class="mono">${esc(response.evidence_id)}</b></div>${renderCaptureStations(r.station_observations)}<h3>Protocol counts · entire capture</h3><pre class="code">${esc(protocolText)}</pre><h3>In-scope 802.11 observations</h3><pre class="code">${esc(wirelessText)}</pre><h3>In-scope exchange observations</h3><pre class="code">${esc(pairText)}</pre><div class="notice">${esc(r.limitations.join(' '))}</div></div>`;toast(response.duplicate?'Capture already imported; no duplicate record created':'Offline capture evidence saved')
 }catch(e){if(box)box.innerHTML=`<div class="panel-body"><div class="notice error-notice">${esc(e.message||e)}</div></div>`}}
let defenseEvidence=null,defenseCaptureId='',defenseResult=null,labTargets=[];
async function deauthAssessment(){const captures=await api('capture_history');const selected=defenseCaptureId||captures[0]?.id||'';if(selected&&selected!==defenseCaptureId){defenseCaptureId=selected;try{defenseEvidence=await api('capture_analysis',selected)}catch{defenseEvidence=null}}
 const analysis=defenseEvidence?.analysis||{},management=analysis.management_frame_observations||{},frames=[...(management.deauthentication||[]),...(management.disassociation||[])],aps=[...new Set([...frames.map(x=>x.bssid),...Object.keys(management.rsn_pmf_advertisements||{})].filter(Boolean))];
 const selectedAp=defenseEvidence?.selectedAp||aps[0]||'';if(defenseEvidence&&!defenseEvidence.selectedAp)defenseEvidence.selectedAp=selectedAp;const targets=window.WiFiSentinelCapabilityState.deauthTargets(frames,selectedAp);
 return `<div class="hero"><h2>Defensive deauthentication assessment</h2><div class="muted">Passive mode analyzes saved PCAP evidence. Lab mode is software-only. No forged frames or deauthentication traffic are transmitted.</div></div><div class="grid g2"><div class="panel"><div class="panel-head"><b>Capture evidence</b><span class="badge">PASSIVE ANALYSIS</span></div><div class="panel-body"><label>Persisted capture<select id="defense-capture" onchange="loadDeauthEvidence(this.value)"><option value="">Choose capture</option>${captures.map(x=>`<option value="${esc(x.id)}" ${x.id===selected?'selected':''}>${esc(x.filename)} · ${esc(x.imported_at)}</option>`).join('')}</select></label><label>Observed AP BSSID<select id="defense-ap" onchange="selectDeauthAp(this.value)"><option value="">Choose observed AP</option>${aps.map(x=>`<option value="${esc(x)}" ${x===defenseEvidence?.selectedAp?'selected':''}>${esc(x)}</option>`).join('')}</select></label><div id="defense-targets">${targets.map((x,i)=>`<label class="check"><input type="checkbox" name="defense-target" value="${esc(x)}" ${i===0?'checked':''}> ${esc(x)}</label>`).join('')||'<div class="empty">No deauthentication/disassociation endpoint observations in the selected capture.</div>'}</div><label class="check"><input id="defense-authorized" type="checkbox"> I am authorized to assess this saved capture within its declared scope.</label><button class="primary" onclick="runDeauthAssessment('passive')" ${!aps.length?'disabled':''}>Analyze selected targets</button></div></div><div class="panel"><div class="panel-head"><b>Lab simulator</b><span class="badge sev-simulation">SIMULATION ONLY</span></div><div class="panel-body"><p class="muted">Generates synthetic target labels in this session. These records are stored as simulation evidence and never enter live discovery.</p><button class="ghost" onclick="generateLabTargets()">Generate synthetic targets</button><div id="lab-target-list">${labTargets.map(x=>`<label class="check"><input type="checkbox" name="lab-target" value="${esc(x)}" checked> ${esc(x)} · SIMULATED</label>`).join('')}</div><button class="ghost" onclick="runDeauthAssessment('simulation')" ${labTargets.length?'':'disabled'}>Run lab simulation</button><div class="notice" style="margin-top:12px">Real deauthentication test: <b>Not supported</b>.</div></div></div></div>${defenseResult?`<div class="panel" style="margin-top:14px"><div class="panel-head"><b>${defenseResult.mode==='simulation'?'SIMULATED RESULT':'Passive analysis result'}</b><span>${badge(defenseResult.status)}</span></div><div class="panel-body"><pre class="code">${esc(JSON.stringify(defenseResult.result||defenseResult,null,2))}</pre></div></div>`:''}`}
async function loadDeauthEvidence(id){defenseCaptureId=id;defenseEvidence=id?await api('capture_analysis',id):null;defenseResult=null;await render()}
async function generateLabTargets(){const x=await api('create_lab_targets',3);labTargets=x.targets||[];await render()}
async function runDeauthAssessment(mode){if(!window.WiFiSentinelCapabilityState.deauthModeSupported(mode)){toast('Live deauthentication is not supported');return}if(!$('#defense-authorized')?.checked&&mode==='passive'){toast('Confirm authorization before passive assessment');return}try{const targets=Array.from(document.querySelectorAll(`input[name="${mode==='passive'?'defense-target':'lab-target'}"]:checked`)).map(x=>x.value);if(!targets.length)throw Error('Select one or more targets.');defenseResult=await api('run_deauth_assessment',mode,defenseCaptureId,$('#defense-ap')?.value,targets,true);await render()}catch(e){toast(e.message||String(e))}}
async function selectDeauthAp(value){if(defenseEvidence)defenseEvidence.selectedAp=value;const management=defenseEvidence?.analysis?.management_frame_observations||{},frames=[...(management.deauthentication||[]),...(management.disassociation||[])],targets=window.WiFiSentinelCapabilityState.deauthTargets(frames,value);const box=$('#defense-targets');if(box)box.innerHTML=targets.map((x,i)=>`<label class="check"><input type="checkbox" name="defense-target" value="${esc(x)}" ${i===0?'checked':''}> ${esc(x)}</label>`).join('')||'<div class="empty">No target identities observed for this AP.</div>'}
let labAPs=[];let labTemplate='minimal';
async function labSimulator(){let snapshot;try{snapshot=await api('live_snapshot')}catch(e){snapshot={wifi:{nearby_aps:[],state:'unavailable',error:e.message}}}const aps=snapshot.wifi?.nearby_aps||[];if(state.pendingLabSsid){if(!labAPs.includes(state.pendingLabSsid))labAPs.push(state.pendingLabSsid);state.pendingLabSsid=''}return `<div class="hero lab-hero"><div class="eyebrow">ISOLATED TRAINING WORKSPACE</div><h2>Wireless behavior simulator</h2><div class="muted">Every action on this page is software-only. It never transmits frames, starts an access point, changes firmware, controls physical LEDs, joins a network, or saves credentials.</div><span class="sim-label">SIMULATION · NO RADIO ACTIVITY</span></div>
<div class="grid g2"><div class="panel"><div class="panel-head"><b>Passive deauthentication / PMF exposure review</b><span class="badge">OBSERVATIONS ONLY</span></div><div class="panel-body"><p class="muted">Uses only the current OS scan. Ordinary scans do not expose PMF negotiation details or client behavior, so unavailable evidence stays unknown.</p><div class="kpi">Observed nearby BSSIDs <b>${aps.length}</b></div><div class="kpi">PMF enforcement exposed by scan <b>Not exposed</b></div><div class="kpi">Deauthentication test performed <b>No · passive only</b></div><div class="table-wrap"><table class="table"><thead><tr><th>Observed AP</th><th>BSSID</th><th>PMF evidence</th></tr></thead><tbody>${aps.map(a=>`<tr><td>${ssidLabel(a)}</td><td class="mono">${esc(a.bssid||'Not exposed')}</td><td>Unknown · OS scan does not expose PMF enforcement</td></tr>`).join('')||'<tr><td colspan="3">No nearby AP observations are currently available.</td></tr>'}</tbody></table></div><div class="notice" style="margin-top:10px">Coverage is limited to APs and channels returned by the host OS at ${esc(snapshot.wifi?.observed_at||'an unavailable observation time')}. This is not an all-networks test.</div></div></div>
<div class="panel"><div class="panel-head"><b>Beacon concepts</b><span class="badge">SIMULATED APs ONLY</span></div><div class="panel-body form"><div class="field"><label>SSID source</label><select id="lab-source" onchange="setLabSource()"><option value="defaults">Default training list</option><option value="nearby">Clone a nearby observed name</option><option value="custom">Custom training name</option></select></div><div id="lab-source-detail"><div class="field"><label>Simulated profile</label><select id="lab-default"><option>TrainingNet</option><option>Guest WiFi Lab</option><option>Secure Office Demo</option></select></div></div><button class="primary" onclick="addLabBeacon()">Add simulated AP</button><div class="notice">Names appear only in this simulator. No beacon is broadcast and simulated entries never appear in Wi-Fi Discovery, assessment evidence, or reports.</div><div id="lab-beacons" class="sim-list">${renderLabAPs()}</div></div></div></div>
<div class="grid g2" style="margin-top:14px"><div class="panel"><div class="panel-head"><b>Captive portal awareness exercise</b><span class="badge">LOCAL PREVIEW</span></div><div class="panel-body form"><div class="field"><label>Training template</label><select id="lab-template" onchange="setLabTemplate(this.value)"><option value="minimal">Minimal sign-in awareness</option><option value="travel">Travel Wi-Fi warning</option><option value="workplace">Workplace training portal</option></select></div><div id="portal-preview" class="portal-preview">${portalPreview(labTemplate)}</div><form class="dummy-form" onsubmit="return submitDummy(event)"><label>Dummy username<input autocomplete="off" placeholder="training-user"></label><label>Dummy password<input type="password" autocomplete="new-password" placeholder="Dummy only"></label><button class="ghost" type="submit">Test local interaction</button></form><div id="dummy-result" class="muted">Input stays in the page and is immediately discarded on submit. Do not enter real credentials.</div></div></div>
<div class="panel"><div class="panel-head"><b>Hardware features</b><span class="badge">NOT CONFIGURED</span></div><div class="panel-body"><div class="kpi">OTA firmware update <b>Unavailable · no device integration</b></div><div class="muted">No firmware update is offered. Device model, signed update source, integrity verification and authenticated updater are not configured.</div><div class="kpi" style="margin-top:12px">Physical LED control <b>Unavailable · no device integration</b></div><button class="ghost" onclick="toggleLabLED()">Toggle simulated lab indicator</button><div id="lab-led" class="lab-led"><i></i><span>LAB INDICATOR · SIMULATED OFF</span></div><div class="muted">This indicator is a visual demo only; it does not control a physical device.</div></div></div></div>`}
function renderLabAPs(){return labAPs.length?labAPs.map((x,i)=>`<div class="sim-ap"><span><b>${esc(x)}</b><small>SIMULATED SSID · NOT BROADCAST</small></span><button class="ghost" onclick="removeLabBeacon(${i})">Remove</button></div>`).join(''):'<div class="empty">No simulated AP profiles added.</div>'}
function setLabSource(){const mode=$('#lab-source').value,box=$('#lab-source-detail');if(mode==='nearby'){api('live_snapshot').then(s=>{const a=s.wifi?.nearby_aps||[];box.innerHTML=`<div class="field"><label>Observed name to use in simulation</label><select id="lab-nearby">${a.map((x,i)=>`<option value="${i}">${ssidLabel(x)} · ${esc(x.bssid||'BSSID unavailable')}</option>`).join('')||'<option value="">No observed SSIDs available</option>'}</select></div><div class="muted">Only the SSID text is copied. No live network is cloned or emulated on air.</div>`}).catch(e=>box.textContent=e.message)}else if(mode==='custom')box.innerHTML='<div class="field"><label>Custom training SSID</label><input id="lab-custom" maxlength="32" placeholder="Training example"></div>';else box.innerHTML='<div class="field"><label>Simulated profile</label><select id="lab-default"><option>TrainingNet</option><option>Guest WiFi Lab</option><option>Secure Office Demo</option></select></div>'}
function addLabBeacon(){let mode=$('#lab-source')?.value||'defaults',name=mode==='nearby'?($('#lab-nearby')?.selectedOptions[0]?.textContent.split(' · ')[0]||''):mode==='custom'?$('#lab-custom')?.value.trim():$('#lab-default')?.value;if(!name){toast('Choose or enter a simulated SSID');return}if([...name].length>32){toast('SSID exceeds the 32 character limit');return}labAPs.push(name);$('#lab-beacons').innerHTML=renderLabAPs()}
function removeLabBeacon(i){labAPs.splice(i,1);$('#lab-beacons').innerHTML=renderLabAPs()}
function portalPreview(t){const names={minimal:['Network sign-in','Review the network name before entering information.'],travel:['Travel Wi-Fi safety check','Public networks may imitate familiar names. Verify the provider independently.'],workplace:['Workplace security learning','This training preview does not authenticate or submit credentials.']};let x=names[t]||names.minimal;return `<div class="portal-card"><div class="portal-mark">W</div><h3>${esc(x[0])}</h3><p>${esc(x[1])}</p><span>PREVIEW ONLY · NO SERVER</span></div>`}
function setLabTemplate(t){labTemplate=t;$('#portal-preview').innerHTML=portalPreview(t);$('#dummy-result').textContent='Input stays in the page and is immediately discarded on submit. Do not enter real credentials.'}
function submitDummy(e){e.preventDefault();const f=e.currentTarget;for(const x of f.querySelectorAll('input'))x.value='';$('#dummy-result').textContent='Training interaction recorded only as a local visual event; submitted values were cleared and not stored or transmitted.';return false}
function toggleLabLED(){const el=$('#lab-led');el.classList.toggle('on');el.querySelector('span').textContent='LAB INDICATOR · SIMULATED '+(el.classList.contains('on')?'ON':'OFF')}
let liveTimer=null,liveWarmupTimer=null,liveRequestId=0,liveActiveRequest=null,liveQueuedForce=false;
function stopLivePolling(){liveRequestId++;liveActiveRequest=null;liveQueuedForce=false;if(liveTimer){clearInterval(liveTimer);liveTimer=null}if(liveWarmupTimer){clearTimeout(liveWarmupTimer);liveWarmupTimer=null}}
async function refreshLiveNow(force=false,attempt=0,manual=force,requestId=null){
 if(requestId===null){if(liveActiveRequest!==null){if(force)liveQueuedForce=true;return}requestId=++liveRequestId;liveActiveRequest=requestId}else if(requestId!==liveRequestId)return;
 let retryScheduled=false;
 try{
  if(force&&attempt===0)await api('refresh_live');
  const snap=await api('live_snapshot');if(requestId!==liveRequestId)return;state.networkSnapshot=snap;
  if(state.page==='dashboard'){
   const aps=snap.wifi?.nearby_aps||[];aps.forEach((ap,index)=>{ap._observation_index=index});
   let selected=aps.find(ap=>apIdentity(ap)===state.selectedApKey)||null;
   if(!selected&&state.selectedApRecord){const match=window.WiFiSentinelCapabilityState.matchObservationIndex(state.selectedApRecord,aps);if(match>=0)selected=aps[match]}
   if(!selected&&!state.selectedApRecord)selected=aps[0]||null;
   if(selected){state.selectedApKey=apIdentity(selected);state.selectedApRecord={...selected}}
   else {state.selectedApKey=null;state.aid=null;state.networkReview=null;state.networkAI=null}
   const list=$('#network-list');if(list)list.innerHTML=renderNetworkRows(filteredNetworks(),state.selectedApKey);
   const detail=$('#network-details'),w=snap.wifi||{};
   if(detail)detail.innerHTML=selected?renderNetworkDetail(selected,w,scanSource(w)):'<div class="empty">The previously selected observation is no longer present in the current scan. Select a current row to continue.</div>';
   const status=$('#network-live-state'),stamp=$('#network-last-scan'),error=$('#network-scan-error');
   if(status)status.textContent=window.WiFiSentinelCapabilityState.scanStatus(snap);
   if(stamp)stamp.textContent=`Last successful scan ${w.observed_at||snap.observed_at||'pending'}${snap.cache_age_ms!=null&&snap.collection_error?` · last good ${Math.round(snap.cache_age_ms/1000)}s ago`:''}`;
   if(error){error.textContent=window.WiFiSentinelCapabilityState.scanMessage(snap,w);error.style.display=error.textContent?'block':'none'}
  }else if((state.page==='devices'||state.page==='map')&&!snap.refreshing)await render();
  if(snap.refreshing&&attempt<60){retryScheduled=true;setTimeout(()=>refreshLiveNow(false,attempt+1,manual,requestId),350)}
 }catch(e){if(manual)toast(e.message||String(e))}
 finally{if(!retryScheduled&&liveActiveRequest===requestId){liveActiveRequest=null;if(liveQueuedForce){liveQueuedForce=false;refreshLiveNow(true)}}}
}
function startLivePolling(){stopLivePolling();if(['dashboard','devices','map'].includes(state.page)){liveWarmupTimer=setTimeout(()=>{liveWarmupTimer=null;if(!document.hidden)refreshLiveNow()},500);liveTimer=setInterval(()=>{if(!document.hidden)refreshLiveNow()},12000)}}
const _render=render;
render=async function(){clearWifiCredential();stopLivePolling();await _render();startLivePolling()};
$('#theme').onclick=toggleTheme;$('#refresh').onclick=()=>['dashboard','devices','map'].includes(state.page)?refreshLiveNow(true):render();nav();if(B){api('settings').then(s=>applyTheme(s.theme)).catch(()=>{});render()}else $('#app').innerHTML='<div class="content page-loading"><div class="loading-card"><span class="spinner"></span><div><b>Starting local engine</b><div class="muted">Waiting for the desktop bridge.</div></div></div></div>';window.addEventListener('pywebviewready',()=>{B=window.pywebview.api;render();api('settings').then(s=>applyTheme(s.theme)).catch(()=>{})});
